-- Paste into the Supabase SQL editor and run.
-- NOTE: a spec draft with slug "food-and-drink-movies" already exists; this script will ADD to it.

BEGIN;

-- 1. The spec draft itself (goes last in the display order, like the admin "create" button)
INSERT INTO public.spec_drafts (name, slug, description, display_order)
VALUES ('Food and Drink Movies', 'food-and-drink-movies', 'Films about food and drink: restaurants and chefs, wine, beer, coffee, sweets and everything in between.',
        (SELECT COALESCE(MAX(display_order), 0) + 1 FROM public.spec_drafts))
ON CONFLICT (slug) DO NOTHING;

-- 2. The custom category
INSERT INTO public.spec_draft_categories (spec_draft_id, category_name)
SELECT id, 'Restaurants' FROM public.spec_drafts WHERE slug = 'food-and-drink-movies'
ON CONFLICT (spec_draft_id, category_name) DO NOTHING;

-- 3. The movies
INSERT INTO public.spec_draft_movies
  (spec_draft_id, movie_tmdb_id, movie_title, movie_year, movie_poster_path, movie_genres, movie_overview,
   oscar_status, revenue, is_sequel, sequel_enriched_at)
SELECT sd.id, v.tmdb_id::integer, v.title, v.year::integer, v.poster, v.genres::integer[], v.overview,
       v.oscar, v.revenue::bigint, v.is_sequel::boolean, now()
FROM public.spec_drafts sd
CROSS JOIN (VALUES
    (9726, 'A Good Year', 2006, '/10ErazhJxfL68rWg2KLfwiRuIou.jpg', '{18,35,10749}', 'Failed London banker Max Skinner inherits his uncle''s vineyard in Provence, where he spent many childhood holidays. Upon his arrival, he meets a woman from California who tells Max she is his long-lost cousin and that the property is hers.', 'none', 42064105, false),
    (236017, 'A Hound for Trouble', 1951, '/5Ay7EkGlPpRgzDfYDUciqglvI4v.jpg', '{16}', 'Kicked off the boat in Italy, Charlie forces himself upon a pizzeria owner. Donning his best Italian accent and garb, Charlie sets to work as a waiter, astonishing and horrifying the customers with his barefoot grape-stomping and musical rendition of "Atsa Matta for You?"', 'none', 0, false),
    (252772, 'A Man About the House', 1947, '/2cef4ROGMyIoHIFJP55jsMb1mqT.jpg', '{18}', 'Handsome Italian laborer Kieron Moore works as caretaker of the Neopolitan villa inherited by plain-Jane Englishwomen Margaret Johnston and Dulcie Gray. Johnston is swept off her feet by the raffishly charming Moore, and before long they are wed.', 'none', 0, false),
    (82259, 'A Matter of Taste: Serving Up Paul Liebrandt', 2011, '/ooyIIScNZOi7qC6H9y7NZ1n1zLc.jpg', '{99}', 'Paul Liebrandt is one of the most talented and controversial chefs in the food world and the youngest chef to have received 3 stars from the New York Times. He was 24. NY Times food critic, William Grimes, likened Paul to ''a pianist who seems to have found a couple of dozen extra keys.'' Through Paul, the film reveals the creative process, the extreme hard work, long hours, and dedication it takes to be a culinary artist and have success in the cutthroat world of haute cuisine. Exploring the complicated relationships between food critics, chefs, and owners the film delves into the life of a dedicated young chef ahead of his time.', 'none', 0, false),
    (84198, 'A Place at the Table', 2012, '/ptli8HtDrapZdVdBnYSN8zxJtw0.jpg', '{99}', 'Using personal stories, this powerful documentary illuminates the plight of the 49 million Americans struggling with food insecurity. A single mother, a small-town policeman and a farmer are among those for whom putting food on the table is a daily battle.', 'none', 230522, false),
    (12497, 'A Touch of Spice', 2003, '/vtLPf20exDzczcgxeW5pazWEFGi.jpg', '{18,35}', '"A Touch of Spice" is a story about Fanis, a young Greek boy growing up in Istanbul, whose grandfather, a culinary philosopher and mentor, teaches him that both food and life require a little salt to give them flavor. They both require... A Touch of Spice. Fanis grows up to become an excellent cook and uses his cooking skills to spice up the lives of those around him. 35 years later he leaves Athens and travels back to his birthplace of Istanbul to reunite with his grandfather and his first love. He travels back only to realize that he forgot to put a little bit of spice in his own life.', 'none', 0, false),
    (9560, 'A Walk in the Clouds', 1995, '/xencQzZnUWDRAOUydjf9PWet8Ae.jpg', '{18,10749}', 'World War II vet Paul Sutton falls for a pregnant and unwed woman who persuades him -- during their first encounter -- to pose as her husband so she can face her family.', 'none', 50012507, false),
    (85658, 'All In This Tea', 2007, '/yYdoAXmDiI5hrgLXwOFhC7U2U40.jpg', '{99}', 'World-renowned tea expert David Lee Hoffman explores remote regions of China in search of the best handmade teas in existence.', 'none', 0, false),
    (35700, 'American Beer', 2004, '/xOPS9AjcqdOHklAjJiipHaTPhb5.jpg', '{}', 'American Beer is a feature-length documentary directed by Paul Kermizian that chronicles and documents the American craft brewing industry. The film was shot in the spring of 2002. Kermizian and a group of four left New York City and traveled by minivan across the United States visiting 38 craft and independent breweries in 40 days.', 'none', 0, false),
    (13158, 'Aqua Teen Hunger Force Colon Movie Film for Theaters', 2007, '/q3Ln4x4rv4nJsBBfukjvH2wiU28.jpg', '{12,14,16,28,35}', 'An action epic that explores the origins of the Aqua Teen Hunger Force (better known as Master Shake, Frylock, and Meatwad,) who somehow become pitted in a battle over an immortal piece of exercise equipment.', 'none', 5500000, false),
    (24224, 'Higher Love', 1998, '/j5fQULGa3XcEweQa46fCgxlqFRX.jpg', '{35,10749}', 'Ross, who lives with his eccentric Uncle Cullen, is desperately trying to become a successful businessman. When he attempts to sell the family wine collection to finance a new venture, his uncle hatches a plan to remind Ross of the talent he left behind.', 'none', 0, false),
    (2182, 'Attack of the Killer Tomatoes!', 1978, '/flCZ7TcuFsT8K5pz6vDZ0Gjk7Nu.jpg', '{27,35}', 'After a wave of reports of mysterious attacks involving people and pets being eaten by the traditionally docile fruit, a special government task force is set up to investigate the violent fruit and put a stop to their murderous spree.', 'none', 567000, false),
    (10239, 'An Autumn Tale', 1998, '/1DQYFB5DENLWKUYdz5ttaVbDYnk.jpg', '{18,10749}', 'Magali, forty-something, is a winemaker and a widow: she loves her work but feels lonely. Her friends Rosine  and Isabelle both want secretly to find a husband for Magali.', 'none', 0, true),
    (11832, 'Babette''s Feast', 1987, '/3ibptSbnAHd0SUBnOKapNZQBpCl.jpg', '{18,35,36}', 'A French housekeeper with a mysterious past brings quiet revolution in the form of one exquisite meal to a circle of starkly pious villagers in late 19th century Denmark.', 'winner', 4398938, false),
    (432087, 'Back to Burgundy', 2017, '/m8Y433w0oaFyZnBUhXv5H180aqU.jpg', '{18,35}', 'Jean left his hometown ten years ago. When his father falls ill, he comes back and reunites with his sister Juliette and his brother Jérémie. As seasons go by around their vineyard, they''ll have to trust each other again.', 'none', 0, false),
    (57737, 'Barbie: A Fairy Secret', 2011, '/wn2aoYKOonwMNKkzfgO5y4ji8pB.jpg', '{14,16,10751}', 'Barbie realises that fairies secretly surround everybody. She, along with the help of her friends, Taylor and Carrie, sets out to rescue Ken. He is taken to the secret fairy city, Gloss Angeles.', 'none', 0, false),
    (44874, 'Barbie: A Fashion Fairytale', 2010, '/bFnf8f8DXdCANQ7Y62djgubhh4P.jpg', '{16,10751}', 'Barbie, a popular actress on a sabbatical, learns that her fashion designer aunt Millicent has sold her business to a rival. With the help of a few magical beings, Barbie steps in to save the day.', 'none', 0, false),
    (359440, 'Barista', 2015, '/mZQw5T4ybWQ7XuadqyGdyRwwHpz.jpg', '{99}', 'Five top baristas find themselves pushing the limits of coffee perfection to win the National Barista Championship - a surreal competition where even one mistake is far too many.', 'none', 0, false),
    (297784, 'Barolo Boys: The Story of a Revolution', 2014, '/1kh3H1PYOR5V0m9hLzIDJgljtlk.jpg', '{99}', 'The story of a group of friends, the "rebel boys" who made italian wine become so great, between generational conflicts, brilliant insights and never silenced controversies.', 'none', 0, false),
    (271715, 'Basmati Blues', 2017, '/8MR9Qiwfpi4ztGXe3MrIQOnX65r.jpg', '{35,10402,10749}', 'Linda Watt is a sheltered but brilliant young scientist who is plucked out of her company''s lab and sent to India by her CEO to sell "Rice 9," a genetically modified rice she''s created. However, unbeknownst to her, the rice will destroy the Indian farmers she thinks she''s helping.', 'none', 0, false),
    (19837, 'Beer Wars', 2009, '/qNVZotUv3o6sG2dTQZT52K2NqOo.jpg', '{99}', 'In America, size matters. The bigger you are, the more power you have, especially in the business world. Anat Baron takes you on a no holds barred exploration of the U.S. beer industry that ultimately reveals the truth behind the label of your favorite beer. Told from an insider’s perspective, the film goes behind the scenes of the daily battles and all out wars that dominate the industry.', 'none', 0, false),
    (9988, 'Beerfest', 2006, '/5srGbSv3zhEUjXFOZR9qHkgJO6l.jpg', '{35}', 'During a trip to Germany to scatter their grandfather''s ashes, German-American brothers Todd and Jan discover Beerfest, the secret Olympics of downing stout, and want to enter the contest to defend their family''s beer-guzzling honor. Their Old Country cousins sneer at the Yanks'' chances, prompting the siblings to return to America to prepare for a showdown the following year.', 'none', 19179969, false),
    (156509, 'Betty Boop''s Bizzy Bee', 1932, '/AuoICzAwZf2GpTkL8nD2t5pxbjZ.jpg', '{16,35}', 'Everyone loves the wheat cakes served by short-order cook Betty, but they have a drawback. With Bimbo and Koko; no bee is involved.', 'none', 0, false),
    (18203, 'Big Night', 1996, '/8AJGSDyrj3Dz2B57n1ZB4qNPbmJ.jpg', '{18,35,10749}', 'Primo and Secondo, two immigrant brothers, pin their hopes on a banquet honoring Louis Prima to save their struggling restaurant.', 'none', 12000000, false),
    (108540, 'Bill W.', 2012, '/xndrcDsVkn1H1cGuChqeMLxp3Dw.jpg', '{99}', 'William G. Wilson is co-founder of Alcoholics Anonymous, a man included in TIME Magazine''s "100 Persons of the 20th Century." Interviews, recreations, and rare archival material reveal how Bill Wilson, a hopeless drunk near death from his alcoholism, found a way out of his own addiction and then forged a path for countless others to follow. With Bill as its driving force, A.A. grew from a handful of men to a worldwide fellowship of over 2 million men and women - a success that made him an icon within A.A., but also an alcoholic unable to be a member of the very society he had created. A reluctant hero, Bill Wilson lived a life of sacrifice and service, and left a legacy that continues every day, all around the world.', 'none', 0, false),
    (46905, 'Black Coffee', 2007, '/o5S8KS0KxSAlHkefrXeaaURNLtc.jpg', '{99}', 'Black Coffee is a 2007 Canadian documentary film examining the complicated history of coffee and detailing its political, social, and economic influence from the past to the present day. The film details how coffee is the eighth most traded legal commodity in the world. It is also the fourth most valuable agricultural commodity. However, only one cent of a $2 cup of coffee goes to the grower.[1] This inequality has helped shape the history of continents and the Cold War.', 'none', 0, false),
    (49952, 'Black Gold', 2006, '/xwwGWmYjLooTArdaSMHYtLZjmM8.jpg', '{99}', 'An in-depth look at the world of coffee and global trade.', 'none', 93477, false),
    (37259, 'Blood Into Wine', 2010, '/frbuHxu3vkoykAJvwDbjAuOSBZY.jpg', '{99}', 'Music fans know Maynard James Keenan as the frontman of such bands as Tool, A Perfect Circle, and Puscifer, but in this documentary filmmakers Christopher Pomerenke and Ryan Page offer a closer look at one of the prolific rocker''s more unexpected hobbies -- winemaking. Along with his business partner Eric Glomski, Keenan has managed to transform an arid stretch of Arizona desert into a lush vineyard that yields some particularly tasty grapes. Through unguarded conversations with Keenan and Glomski, Pomerenke and Page discover just what got the pair interested in winemaking, and why they chose such a hostile natural environment to serve as the site of their winery.', 'none', 0, false),
    (162705, 'Bosko''s Soda Fountain', 1931, '/xLUngR1hjGmVVbzK1PSx2KxiKpy.jpg', '{16,35}', 'Bosko is a soda jerk, who gives poor service to a mouse and to his former schoolteacher. Later, he must contend with Honey''s bratty Wilbur.', 'none', 0, false),
    (13996, 'Bottle Shock', 2008, '/DMc4eRfU0RA2SX2oGR3YllEhH7.jpg', '{18,35}', 'Paris-based wine expert Steven Spurrier heads to California in search of cheap wine that he can use for a blind taste test in the French capital. Stumbling upon the Napa Valley, the stuck-up Englishman is shocked to discover a winery turning out top-notch chardonnay. Determined to make a name for himself, he sets about getting the booze back to Paris.', 'none', 4040588, false),
    (135598, 'Bread of Happiness', 2012, '/6bobuzQbQpN4FrcakPC8zSZoRif.jpg', '{18,35}', 'A couple decide to relocate from Tokyo to the northern island of Hokkaido where they settle and establish a bakery and café called Mani. One cooks. The other bakes. Everyone walks out happy.', 'none', 0, false),
    (295964, 'Burnt', 2015, '/iptu4zfvbeULkeuoVkTl2mOqTPS.jpg', '{18}', 'Adam Jones is a Chef who destroyed his career with drugs and diva behavior. He cleans up and returns to London, determined to redeem himself by spearheading a top restaurant that can gain three Michelin stars.', 'none', 36606743, false),
    (69585, 'Cafe Isobe', 2008, '/mzOcFGuesQOlwxiHxR3XyGS5Ce4.jpg', '{35}', 'Sakiko is a typical teenager in many ways. She hates her divorced father, who chases after every skirt he sees. She does not know, if she will ever be loved by the other sex. When her dad suddenly inherits a lot of money and becomes really lazy, she hates him even more. He finally decides to start his own cafe, where Sakiko, of course has to help. From this moment, strange customers and good-looking waitresses form the center of tension between father and daughter.', 'none', 0, false),
    (287703, 'Café. Waiting. Love', 2014, '/xNQqkpBT2LfZFvsdlF5rGTldfwd.jpg', '{14,35,10749}', 'College freshman Si-ying gets a part-time job at “Cafe. Waiting. Love” coffee shop, where she befriends Abusi, a tomboyish barista who can make any coffee the customers request, the beautiful and mysterious cafe owner, and Zeyu, the boy who always sits in the same spot in the cafe who seems to be very popular with girls and on whom Si-ying develops an instant crush.', 'none', 4747792, false),
    (118, 'Charlie and the Chocolate Factory', 2005, '/iKP6wg3c6COUe8gYutoGG7qcPnO.jpg', '{12,14,35,10751}', 'A young boy wins a tour through the most magnificent chocolate factory in the world, led by the world''s most unusual candy maker.', 'nominee', 475000000, false),
    (191260, 'Cheer Boys Cheer', 1939, '/sIJs1yciH7617lgWeUWxMmQrLPw.jpg', '{35}', 'Shades of "Romeo and Juliet" with rival British Brewery owners who hate each other and their children who fall in love.', 'none', 0, false),
    (212778, 'Chef', 2014, '/hyp8EXDmO4dSC8V6Q5jU7gD1kcg.jpg', '{35}', 'When Chef Carl Casper suddenly quits his job at a prominent Los Angeles restaurant after refusing to compromise his creative integrity for its controlling owner, he is left to figure out what''s next. Finding himself in Miami, he teams up with his ex-wife, his friend and his son to launch a food truck. Taking to the road, Chef Carl goes back to his roots to reignite his passion for the kitchen -- and zest for life and love.', 'none', 50440695, false),
    (254760, 'Chez Schwartz', 2007, NULL, '{99}', 'Chez Schwartz takes us inside a year in the life of Schwartz''s Deli - the unique 75-year-old landmark on Montreal''s historic Main. Filmed through changing seasons, from the quiet of early morning preparation to the frenetic bustle of packed lunch times and never ending line-ups, to the more relaxed ambiance late at night - Chez Schwartz is an evocative, cinematic portrait of a small spunky deli known worldwide equally for its atmosphere and smoked meat.', 'none', 0, false),
    (392, 'Chocolat', 2000, '/lnwPvyj8UR7MetG2pQ92453IIoR.jpg', '{18,35,10749}', 'In the winter of 1959, a single mother and her young daughter arrive in a rural French town, where they open an unusual chocolate shop that disrupts the moral fiber of the strictly Catholic townsfolk and mayor.', 'nominee', 152700626, false),
    (13973, 'Choke', 2008, '/7osy71os3YLiFpNYn567koOnAKZ.jpg', '{18,35}', 'A sex-addicted con-man pays for his mother''s hospital bills by playing on the sympathies of those who rescue him from choking to death.', 'none', 3982459, false),
    (34778, 'Christmas in July', 1940, '/sxbBYi198Zgj4cix3VCL4s0wH4X.jpg', '{35,10749}', 'An office clerk loves entering contests in the hopes of someday winning a fortune and marrying the girl he loves. His latest attempt is the Maxford House Coffee Slogan Contest. As a joke, some of his co-workers put together a fake telegram which says that he won the $25,000 grand prize.', 'none', 0, false),
    (2295, 'Clerks II', 2006, '/cLSW0nW94XT0DmBS69ublcLfQ9c.jpg', '{35}', 'A calamity at Dante and Randall''s shops sends them looking for new horizons - but they ultimately settle at Mooby''s, a fictional Disney-McDonald''s-style fast-food empire.', 'none', 26986174, true),
    (22794, 'Cloudy with a Chance of Meatballs', 2009, '/qhOhIKf7QEyQ5dMrRUqs5eTX1Oq.jpg', '{16,35,10751}', 'Inventor Flint Lockwood creates a machine that makes clouds rain food, enabling the down-and-out citizens of Chewandswallow to feed themselves. But when the falling food reaches gargantuan proportions, Flint must scramble to avert disaster. Can he regain control of the machine and put an end to the wild weather before the town is destroyed?', 'none', 242988466, false),
    (109451, 'Cloudy with a Chance of Meatballs 2', 2013, '/ss5NcK2NWFg2YcKKYXLrk8q1myS.jpg', '{16,35,10751}', 'After the disastrous food storm in the first film, Flint and his friends are forced to leave the town. Flint accepts the invitation from his idol Chester V to join The Live Corp Company, which has been tasked to clean the island, and where the best inventors in the world create technologies for the betterment of mankind. When Flint discovers that his machine still operates and now creates mutant food beasts like living pickles, hungry tacodiles, shrimpanzees and apple pie-thons, he and his friends must return to save the world.', 'none', 248384621, true),
    (7520, 'Cocktail', 1988, '/jFRhEPhtsln9tDwzMdZN3OlhUob.jpg', '{18,35,10749}', 'After being discharged from the Army, Brian Flanagan moves back to Queens and takes a job in a bar run by Doug Coughlin, who teaches Brian the fine art of bar-tending. Brian quickly becomes a patron favorite with his flashy drink-mixing style, and Brian adopts his mentor''s cynical philosophy on life and goes for the money.', 'none', 171504781, false),
    (41643, 'Combination Platter', 1993, '/8hyQ3fDWVBv3X9HPwzudf3lJCxe.jpg', '{18}', 'An employee at a Chinese Restaurant in New York City tries desperately to obtain a green card by marrying an American woman.', 'none', 0, false),
    (84188, 'Compliance', 2012, '/bLdu28fr9txYlHLmEOyGplDT3nH.jpg', '{18,53}', 'On a particularly busy day at a suburban Ohio fast food restaurant, manager Sandra receives a phone call from a police officer saying that an employee has stolen money from a customer.', 'none', 592116, false),
    (438857, 'Cook Up a Storm', 2017, '/jHMVa4VWLxggvbDo2Ol1ln4obJs.jpg', '{18,35}', 'An international culinary competition becomes a battleground between rival cooks, one famous for his Cantonese street food and the other a Michelin-starred chef trained in France. But their rivalry takes an unexpected turn when they discover a common foe and combine their skills in a fusion of East and West.', 'none', 0, false),
    (68987, 'Cooking With Stella', 2010, '/pwuJN7G9Mjl4heNgsYGtM6PfZQ2.jpg', '{18,35}', 'Inside the Canadian diplomatic compound in New Delhi, a mischievous cook affects the lives of her employers and fellow staff.', 'none', 0, false),
    (89659, 'Criminally Insane', 1975, '/5z5DvkdCz2mNHzFBBtU2TQA8oGI.jpg', '{27,35}', 'An obese woman recently released from an insane asylum kills anyone who attempts to get her to stop eating.', 'none', 0, false),
    (163447, 'Criminally Insane 2', 1987, '/7Lk1kHyHoEkYrvGlRG67QNcB8vV.jpg', '{27}', 'A mental hospital, faced with a severe decrease in funding, is forced to release mass-murderer Ethel Janowski into a halfway house. Ethel is psychotic, delusional and has a hefty appetite. In fact, her killing spree began 13 years before with the murder of her grandmother, who had forced her to go on a diet. Now that she''s tasted the home-cooked fare at the halfway house, she''ll do absolutely anything to get more.', 'none', 0, true),
    (223310, 'Devour the Earth', 1995, NULL, '{99}', 'Devour the Earth, a 20 minute film about the global consequences of meat consumption.', 'none', 0, false),
    (13776, 'Diner', 1982, '/2vKIdZ6JkFIzcQeaHg3xtdvOyRO.jpg', '{18,35}', 'Set in 1959, Diner shows how five young men resist their adulthood and seek refuge in their beloved Diner. The mundane, childish, and titillating details of their lives are shared. But the golden moments pass, and the men shoulder their responsibilities, leaving the Diner behind.', 'nominee', 14100000, false),
    (22617, 'Dinner Rush', 2000, '/6qhSssp1RT3IU53OkomdpJsyJ0D.jpg', '{18,28,53}', 'One unlucky evening, Louis Cropa, a part-time bookmaker, discovers that his restaurant has become a hotbed of conflicting characters. In addition to having to please a whiny food critic, Louis must fend off a hostile takeover from a pair of gangsters, to whom his sous-chef is in debt. Further, Louis has an argument with his son, the star chef, whose culinary creativity has brought success to the business.', 'none', 1075504, false),
    (82642, 'Dive!', 2010, '/nEVAgf3IypITVVoQ7sDMjzT6kW6.jpg', '{99}', 'Follow filmmaker Jeremy Seifert and his circle of friends as they dumpster dive in the back alleys and gated garbage receptacles of L.A.''s supermarkets. In the process they uncover thousands of dollars worth of good food and an ugly truth about waste in America: grocery stores know they are wasting and most refuse to do anything about it.', 'none', 0, false),
    (727551, 'Double Patty', 2021, '/kRV7eLTiQefmJ6eYYtpypFP4lAS.jpg', '{18,10749}', 'Kang Woo-ram is busy preparing to get a job. Lee Hyun-ji is a would-be anchor, but she works at a homemade hamburger restaurant. One night, Woo-ram visits the hamburger restaurant and orders a double patty hamburger, which has a "buy one, get one free" sale. This is how their relationship begins.', 'none', 0, false),
    (172533, 'Drinking Buddies', 2013, '/iunbsMWtkwfrtRzU7hdCHhPjjJf.jpg', '{18,35,10749}', 'Weekend trips, office parties, late night conversations, drinking on the job, marriage pressure, biological clocks, holding eye contact a second too long… you know what makes the line between “friends” and “more than friends” really blurry? Beer.', 'none', 343341, false),
    (30238, 'Earthlings', 2005, '/fcRUYYyDWLJPlX7D6RPtQwdU7G2.jpg', '{99}', 'Using hidden cameras and never-before-seen footage, Earthlings chronicles the day-to-day practices of the largest industries in the world, all of which rely entirely on animals for profit.', 'none', 0, false),
    (257245, 'East Side Sushi', 2014, '/hyDJxhPooTZQ3F889qxHyAUzBfO.jpg', '{18}', 'Years of working in the food industry have made Juana, a working-class Latina, a chef of speed and skill. Searching for financial stability, she stumbles into a high-energy, male-dominated Japanese cuisine kitchen. The new atmosphere re-ignites her passions for food and life and makes her hungry to get mixed up in the flavors of this new world.', 'none', 0, false),
    (10451, 'Eat Drink Man Woman', 1994, '/olhIWtIBFg6VWK59DEd4lAvgVgz.jpg', '{18,35,10749}', 'Retired and widowed Chinese master chef Chu lives in modern day Taipei, with his three attractive daughters, all of whom are unattached. Soon, each daughter encounters a new man in their lives. When these new relationships blossom, stereotypes are broken and the living situation within the family changes.', 'nominee', 24194403, false),
    (69335, 'Estômago: A Gastronomic Story', 2007, '/mo9utQQ9nurl2ELWUzS4e3WHGDm.jpg', '{18,35,80,9648}', 'In a dog-eat-dog world, Raimundo Nonato has found an alternative way to move ahead: he cooks. No matter what social strata this deceptively innocent young man inhabits, he hones his skills and sharpens his knives—and then he falls in love. Jorge''s nimble comic fable provides a smartly constructed gastronomic allegory for ambition and survival.', 'none', 0, false),
    (567646, 'Extreme Job', 2019, '/52oLgq2gEiZyDjpJ7tgkGruoQI0.jpg', '{28,35,80}', 'A drug squad attempts to take down a criminal organization and they must go undercover to do so, so they begin working at a chicken restaurant, that becomes famous for its delicious chicken. Due to the unexpected popularity, the detectives find themselves in a situation they never expected.', 'none', 124652206, false),
    (3051, 'Eye of the Devil', 1966, '/9GTqeKBdjJ12wme4ygP4eyqRiqp.jpg', '{27,53,9648}', 'A French nobleman deserts his wife because of an ancient family secret.', 'none', 0, false),
    (8324, 'Fast Food Nation', 2006, '/vcRgWIj4p6FtezgZTl4YoxYbSJ7.jpg', '{18,35}', 'A dramatised examination of the health issues and social consequences of America''s love affair with fast food.', 'none', 2209322, false),
    (36944, 'Fat Head', 2009, '/wIEEV2bqJfZXQcB79DzY1Okb9wD.jpg', '{99}', 'A comedian replies to the "Super Size Me" crowd by losing weight on a fast-food diet while demonstrating that almost everything you think you know about the obesity "epidemic" and healthy eating is wrong.', 'none', 0, false),
    (72914, 'Fat, Sick & Nearly Dead', 2010, '/yKXRwMValA4ZbCaC68ANO24ALcY.jpg', '{99}', '100 pounds overweight, loaded up on steroids and suffering from a debilitating autoimmune disease, Joe Cross is at the end of his rope and the end of his hope. In the mirror he saw a 310lb man whose gut was bigger than a beach ball and a path laid out before him that wouldn''t end well— with one foot already in the grave, the other wasn''t far behind. FAT, SICK &amp; NEARLY DEAD is an inspiring film that chronicles Joe''s personal mission to regain his health.', 'none', 0, false),
    (293299, 'Feast', 2014, '/6hAgSxgd2YIK5pYhwowtnlGpwbe.jpg', '{16,18,35,10751}', 'This Oscar-winning animated short film tells the story of one man''s love life as seen through the eyes of his best friend and dog, Winston, and revealed bite by bite through the meals they share.', 'winner', 0, false),
    (244714, 'Fine Food, Fine Pastries, Open 6 to 9', 1989, '/pMSYwMohjn51rfygwOL4yhCADdW.jpg', '{}', 'Examines the history of Sherrill''s Restaurant and Bakery in Washington, D.C. How a unique restaurant integrates into the culture of the community.', 'nominee', 0, false),
    (541593, 'Fine Gold', 1989, '/wrZvZNcKrM4M1kju1pzqqB0kaET.jpg', '{18}', 'Two European winemaking families'' friendships are destroyed by false accusations after a theft in this melodrama.', 'none', 0, false),
    (26018, 'Food Matters', 2010, '/g1u0Mf4VKKklC8fKsvAh5n5pk8T.jpg', '{99}', 'With nutritionally-depleted foods, chemical additives and our tendency to rely upon pharmaceutical drugs to treat what''s wrong with our malnourished bodies, it''s no wonder that modern society is getting sicker. Food Matters sets about uncovering the trillion dollar worldwide sickness industry and gives people some scientifically verifiable solutions for curing disease naturally.', 'none', 0, false),
    (18570, 'Food, Inc.', 2008, '/zdwN4o7OGAZGJw9T64lRAGTEP8b.jpg', '{99}', 'Documentary filmmaker Robert Kenner examines how mammoth corporations have taken over all aspects of the food chain in the United States, from the farms where our food is grown to the chain restaurants and supermarkets where it''s sold. Narrated by author and activist Eric Schlosser, the film features interviews with average Americans about their dietary habits, commentary from food experts like Michael Pollan and unsettling footage shot inside large-scale animal processing plants.', 'nominee', 4606199, false),
    (116977, 'Foodfight!', 2012, '/to9ggXVyhNTCICHcHMCtFtANd8P.jpg', '{12,16,28,35,10751}', 'The evil Brand X joins a supermarket that becomes a city after closing time.', 'none', 73706, false),
    (549644, 'Foodiverse', 2018, '/hgueB7u35bAYawTsSUvqLLdDWN8.jpg', '{16,35,10751}', 'Grab your space helmet and blast off into a fantastical adventure set in a distant galaxy made entirely of food: the FOODIVERSE! When a maniacal super villan sets out to dominate the foodiverse, our heroes Miss Penny, a little dumpling, and her bestie Mr. Podge, a tubby pork bun, are bound to embark on an intergalactic mission to save the homes they hold so dear.', 'none', 0, false),
    (64288, 'Forks Over Knives', 2011, '/v3SC1ztIEpo41AvF5frURCdvLOx.jpg', '{99}', 'Examines the profound claim that most; if not all; of the degenerative diseases that afflict us can be controlled; or even reversed; by rejecting our present menu of animal-based and processed foods. The idea of food as medicine is put to the test. Cameras follow "reality patients" who have chronic conditions from heart disease to diabetes. Doctors teach these patients how to adopt a whole-foods, plant-based diet as the primary approach to treat their ailments - while the challenges and triumphs of their journeys are revealed.', 'none', 664747, false),
    (85642, 'Garlic Is as Good as Ten Mothers', 1980, '/gcgRpoF7WKcGAXpEGtqRdVo9b7u.jpg', '{99}', 'A zesty paean of praise to the greater glories of garlic. This lip-smacking foray into the history, consumption, cultivation and culinary/curative powers of the stinking rose features chef Alice Waters of Chez Panisse, and a flavorful musical soundtrack.  Preserved by the Academy Film Archive in 1999.', 'none', 0, true),
    (34133, 'Go Further', 2003, '/AproKPuDZ2bP9TQ0tiVvjtTB95p.jpg', '{99}', '"Go Further" explores the idea that the single individual is the key to large-scale transformational change. The film follows actor Woody Harrelson as he takes a small group of friends on a bio-fueled bus-ride down the Pacific Coast Highway. Their goal? To show the people they encounter that there are viable alternatives.', 'none', 0, false),
    (14817, 'Good Burger', 1997, '/imFLUF2TYkm13GpFYTKYF7T27sP.jpg', '{35,10751}', 'Two L.A. teens with summer jobs at Good Burger try to save their small restaurant when a corporate giant burger franchise moves in across the street.', 'none', 23712993, false),
    (262169, 'Gravy', 2015, '/ruskUcYFAy6ctl2ZlTsXqJ7kPCD.jpg', '{27,35}', 'It''s All Hallow''s Eve. A trio of costumed misfits with very special dietary requirements seizes a Mexican cantina and force the staff to engage in a late night of gaming, food and libations. The only caveat is what''s on the menu.', 'none', 0, false),
    (507964, 'Gulabjaam', 2018, '/lrSt1cLjywZ2pwlcY0cqI69ImXL.jpg', '{18,35}', 'Aditya is a young Maharashtrian man from London who comes to Pune to find a someone who would teach him traditional Maharashtrian cooking. His aim is to open a Marathi Gourmet Restaurant in London. In search of a perfect guru, he meets eccentric Radha, a woman who makes lunch boxes for the students and working men in her area. Aditya needs to pass many tests before Radha would accept him as student. But once she starts teaching him, a new path of life opens for Aditya. Gulabjaam is a food film, where Marathi food is almost the third important character.', 'none', 635082, false),
    (161923, 'Ham and Eggs', 1933, '/l4xk65QQ8OWuXNfmKPfhAK3xsdI.jpg', '{16}', 'Oswald runs a luncheon counter; the food is unlikely and everyone tries to stiff him.', 'none', 0, false),
    (766877, 'Hash House Blues', 1931, NULL, '{16}', 'Krazy Kat is the waiter of a fancy restaurant.', 'none', 0, false),
    (139651, 'Haute Cuisine', 2012, '/aEXtMSaAIsHMKBKqKh1OKKnaHdy.jpg', '{18,35}', 'The story of Danièle Delpeuch and how she was appointed as the private chef for François Mitterrand.', 'none', 11384015, false),
    (57089, 'Hoodwinked Too! Hood VS. Evil', 2011, '/3ofAJDO8A7ulJwgMGKcwEOPNWV3.jpg', '{16,35,10751}', 'Red Riding Hood is training in the group of Sister Hoods, when she and the Wolf are called to examine the sudden mysterious disappearance of Hansel and Gretel.', 'none', 13500000, true),
    (10982, 'Hoodwinked!', 2005, '/kwPl1AKX4BLxrh5PCkrwYWeEV5I.jpg', '{16,35,80,9648,10751}', 'Little Red Riding Hood: A classic story, but there''s more to every tale than meets the eye. Before you judge a book by its cover, you''ve got to flip through the pages. In the re-telling of this classic fable, the story begins at the end of the tale and winds its way back. Chief Grizzly and Detective Bill Stork investigate a domestic disturbance at Granny''s cottage, involving a karate-kicking Red Riding Hood, a sarcastic wolf and an oafish Woodsman.', 'none', 110000000, false),
    (50359, 'Hop', 2011, '/2FrDmwXWjRE1zpNP288YncRt5RF.jpg', '{16,35,10751}', 'E.B., the Easter Bunny''s teenage son, heads to Hollywood, determined to become a drummer in a rock ''n'' roll band. In L.A., he''s taken in by Fred after the out-of-work slacker hits E.B. with his car.', 'none', 183953723, false),
    (51069, 'I Like Killing Flies', 2004, '/elr5xGIbVqJtg2Y5KJ7mUmbWTi4.jpg', '{99}', 'In the cramped, cluttered confines of Shopsin’s, a legendary hole-in-the-wall diner in New York’s Greenwich Village, eccentric chef Kenny Shopsin holds court—serving up an absurdly massive menu alongside his razor-sharp wit and unfiltered philosophies on life, food, and human nature. As the family-run institution faces a forced relocation, this intimate documentary captures the controlled chaos of Kenny’s world, where every customer is a character and every meal is a performance. A love letter to stubborn individuality and the art of doing things your own way.', 'none', 14000, false),
    (640092, 'I''m Livin'' It', 2019, '/c9uAvMinfY5qrih7cYnOugBBusT.jpg', '{18}', 'Once a star in his finance firm, Bowen now spends his nights in a 24-hour fast food joint, where he encounters others “roommates” who are in a similar predicament. Together these accidental roommates must strive to lift one another out of rock bottom.', 'none', 0, false),
    (605734, '#Iamhere', 2019, '/yxHDlr90ww0XZt3U26W95JNExf3.jpg', '{35,10749}', 'Stéphane lives a quiet life as an eminent French Chef but when he decides to visit Soo, a mysterious Korean lady he fell in love with on Instagram, he''ll embark on an adventurous journey full of discoveries.', 'none', 0, false),
    (83653, 'Ingredients', 2009, '/nYu0wIcIKCcXxghyTg1J42mKirU.jpg', '{99}', 'At the focal point of this movement, and of this film, are the farmers and chefs who are creating a truly sustainable food system. Their collaborative work has resulted in great tasting food and an explosion of consumer awareness about the benefits of eating local.  Attention being paid to the local food movement comes at a time when the failings of our current industrialized food system are becoming all too clear. For the first time in history, our children''s generation is expected to have a shorter lifespan than our own. The quality, taste and nutritional value of the food we eat has dropped sharply over the last fifty years. Shipped from ever-greater distances, we have literally lost sight of where our food comes from and in the process, we''ve lost a vital connection to our local community and to our health.', 'none', 0, false),
    (254148, 'Choji Snack Bar', 1983, '/yNN0tFy7Nea3EHx3Zyup6tfvUGG.jpg', '{18}', 'Eiji lives a quiet life running a small Izakaya with his wife. He spends his days cooking for and serving the lively residents of his small hometown.', 'none', 0, false),
    (80767, 'Jiro Dreams of Sushi', 2011, '/iVrkM4jSJw1IsOpW5jTtY5QxVqj.jpg', '{99}', 'Revered sushi chef Jiro Ono strives for perfection in his work, while his eldest son, Yoshikazu, has trouble living up to his father''s legacy.', 'none', 2550508, false),
    (24803, 'Julie & Julia', 2009, '/1QZNWOOwfRi86ZApGvr2TtJZPBK.jpg', '{18,10749}', 'Julia Child and Julie Powell – both of whom wrote memoirs – find their lives intertwined. Though separated by time and space, both women are at loose ends... until they discover that with the right combination of passion, fearlessness and butter, anything is possible.', 'nominee', 129500000, false),
    (40635, 'Just Desserts', 2004, '/wpQjwZsPaDp6hUUMY2u6eesPJvf.jpg', '{35,10749}', 'Marco Poloni''s family owns a bakery in the Bronx and it seems that they have fallen on hard times and his family is considering selling the bakery. Marco then decides to enter a baking competition hoping that the money and publicity will help them. But he needs a partner, so her asks Grace Carpenter, the baker of restaurant, but unfortunately they started off on the wrong foot, but she agrees. So they go to the competition and things seem to be looking good except for a few complications. One of the other contestant Jacques du Jacques is Marco''s former classmate at the Academy, whom he says betrayed him. Emil, one of the judges, is Marco''s former instructor at the Academy whom he did not leave a good impression on. And Marco''s temper. So will they be able to pull it off. And at the same time Marco finds himself attracted to her but she already has a boyfriend.', 'none', 0, false),
    (25657, 'Kamome Diner', 2006, '/2J1Pkw1DPMbFRuN07RI6TlZbNmt.jpg', '{18,35}', 'On a quiet street in Helsinki, Sachie has opened a diner featuring rice balls. For a month she has no customers. Then, in short order, she has her first customer, meets Midori, a gangly Japanese tourist, and invites her to stay with her.', 'none', 0, false),
    (36896, 'Killer Tomatoes Eat France!', 1992, '/fLpZEAPtMVlxIY9sxZK1giGPhIK.jpg', '{27,35}', 'After being busted out of jail by his tomatoes, Professor Mortimer Gangreen begins a new plot to take over the world by inserting his hapless lackey Igor into the throne of the King of France.', 'none', 0, true),
    (36779, 'Killer Tomatoes Strike Back!', 1991, '/iPfmzJybBS9fyPBoP0oVND3PkU4.jpg', '{27,35}', 'Police assitant Boyle along with tomatologist Kennedi Johnson look into investigations about Killer Tomato attacks, and discover Gangrene plans to brainwash people via TV talk shows to take over the world! Will Gangrene be stopped? Will Johnson become part of a Bacon, Lettuce and Human sandwich?', 'none', 0, true),
    (57722, 'Kings of Pastry', 2009, '/orLXFuV9WGqczVBJRw1tRHF50o0.jpg', '{99}', 'The collar awarded to the winners of the Meilleur Ouvrier de France (Best Craftsman in France) is more than the ultimate recognition for every pastry chef - it is a dream and an obsession. The 3-day competition includes everything from delicate chocolates to precarious six foot sugar sculptures and requires that the chefs have extraordinary skill, nerves of steel and luck. The film follows Jacquy Pfeiffer, founder of The French Pastry School in Chicago, as he returns to France to compete against 15 of France''s leading pastry chefs. The filmmakers were given first time/exclusive access to this high-stakes drama of passion, sacrifice, disappointment and joy in the quest to have President Sarkozy declare them one of the best in France.', 'none', 0, false),
    (30981, 'Know Your Mushrooms', 2009, '/vz9qyCSyQwQCQCRKnWdMq6sLnqy.jpg', '{99}', 'KNOW YOUR MUSHROOMS follows uber myco visionaries Gary Lincoff and Larry Evans (two of the more expert and unforgettably mercurial characters in the community) as they lead us on a hunt for the wild mushroom and the deeper cultural experiences attached to the mysterious fungi.', 'none', 0, false),
    (1121366, 'Krazy Kat Invalid', 1916, NULL, '{16}', 'Krazy Kat Invalid is a silent short animated film distributed by Hearst-Vitagraph News Pictorial, and featuring Krazy Kat in one of the character''s earliest animated appearances', 'none', 0, false),
    (25124, 'Kung Fu Chefs', 2009, '/ar4OpI2E1DmC7nvUz1O349CfEZp.jpg', '{28,35}', 'Ousted chef Wong Bing-Yi is determined to help Shen Qing at her restaurant "Four Seas". He trains a young chef, Lung Kin-Yat to compete against Chef Tin, the head chef at "Imperial Palace", for the title of "Top Chef".', 'none', 0, false),
    (104435, 'The Beehive', 1982, '/uJUO2vceur1qsSH7EyfIPzzMs2r.jpg', '{18,35}', 'As in the novel of the same title from Camilo Jose Cela, "La Colmena" is a sad composition with the stories of many people in the Madrid of 1942, just the postwar of the spanish civil war. The main theme of the film is the contrast between the poets, surviving close to misery under the Franco''s regime, and the winners of the war, the emerging class of the people that makes easy money with illegal business.', 'none', 0, false),
    (10102, 'La Grande Bouffe', 1973, '/g4wOgslrQKprlQl927h0lQQ3P99.jpg', '{18,35}', 'Four friends gather at a villa with the intention of eating themselves to death.', 'none', 0, false),
    (166977, 'Laughing Heirs', 1933, '/phiKGjZCjAIVJTD9xDpjJBlhBXV.jpg', '{35,10749}', 'After the death of his uncle, the owner of the Rhine based Bockelmann Sparkling Wine, Peter turns up for the reading of the will. Justus Bockelmann, a producer of mineral water, is confident he will inherit the business, but ‘for reasons of moral rectitude’ he has no intention of running an ‘alcoholic business’. The opening of the will comes as a surprise to all the potential heirs.', 'none', 0, false),
    (82406, 'Le Grand Chef', 2007, '/zCizXVuPbEQxECnB5uh7go4OTyV.jpg', '{18,35}', 'A disgraced chef tries to restore his name by competing in a culinary contest to win the knife of Korea''s last royal chef.', 'none', 0, false),
    (72857, 'Le Grand Chef 2: Kimchi Battle', 2010, '/jV1sXA1zvm9DeSfZ7WfjW5WGD8V.jpg', '{35}', 'A talented chef battles her stepbrother in a government-sponsored cooking contest, with national pride and the fate of their struggling family restaurant hanging in the balance.', 'none', 0, true),
    (29107, 'The Grapes of Death', 1978, '/hYkAuNKiHtiFZrakxLtNbqgDO9Q.jpg', '{27}', 'A young woman discovers that the pesticide being sprayed on vineyards is turning people into murderous lunatics.', 'none', 0, false),
    (22182, 'Lessons in Chocolate', 2007, '/hc8slQloUKloVbUnGdRZk4CVd7p.jpg', '{35}', 'Mattia, a building contractor on a promising career path, is about to close the biggest deal of his professional life, when his illegally-hired worker Kamal falls off some scaffolding, suffers a severe break and threatens to sue and press charges against Mattia unless... Unless Mattia takes his place in an advanced course for pastry makers! This is the reason Kamal came to Italy from his native Egypt and that will allow him to realize his dream of opening his own pastry shop... Mattia has no choice but to take Kamal’s place in the school and pretend to be him. Among laughs and mouth-watering recipes, Mattia will discover a way to bring his and Kamal''s disparate cultures together.', 'none', 0, false),
    (1379, 'Lights in the Dusk', 2006, '/vBn28XPBI4vOKye1NSTGghdvGoJ.jpg', '{18}', 'Outcast by his co-workers and living alone, Koistinen is a security guard who works the night shift in a luxury shopping mall in Helsinki. But when icy blonde Mirja approaches him, the lonely Koistinen falls helplessly for her, unaware she is manipulating him for her criminal boyfriend.', 'none', 1615018, false),
    (18183, 'Like Water for Chocolate', 1991, '/itwUdMqLmPfhtGJ44hiDxkqZhiq.jpg', '{18,10749}', 'Tita is passionately in love with Pedro, but her controlling mother forbids her from marrying him. When Pedro marries her sister, Tita throws herself into her cooking and discovers she can transfer her emotions through the food she prepares, infecting all who eat it with her intense heartbreak.', 'none', 21744201, false),
    (523773, 'Little Italy', 2018, '/vdSSmzYKqViKH7mkQwgOVSALrOO.jpg', '{35,10749}', 'Former childhood pals Leo and Nikki are attracted to each other as adults—but will their feuding parents'' rival pizzerias put a chill on their sizzling romance?', 'none', 0, false),
    (66945, 'Love''s Kitchen', 2011, '/mKedM3lkGfqrXfbJdRuaerFwC7z.jpg', '{18,35,10749}', 'Rob Haley, an up-and-coming chef and restaurateur in London, is grief-stricken when he loses his wife. With encouragement from his infamous friend and real life TV Chef Gordon Ramsay, Rob decides to spice up his life by turning a run-down country pub into a gourmet restaurant. His food catches the eye - and taste buds - of beautiful American food critic Kate Templeton and they soon both write a recipe for love that leaves both their hearts - and their stomachs - in full.', 'none', 0, false),
    (686919, 'Maska', 2020, '/4tYTGLcsuxhmBtiKq57yGqh0xQO.jpg', '{35}', 'Determined to make it in showbiz, an aspiring young actor considers turning his back on the beloved Irani café run by his family for generations.', 'none', 0, false),
    (106065, 'Meet Your Meat', 2002, '/4UYdAhKiCTn4T4OcyFDGas4A7zs.jpg', '{99}', 'In a moving narration, actor and activist Alec Baldwin exposes the truth behind humanity''s cruelest invention: the factory farm.  This documentary explores the treatment of animals in modern animal agriculture (also known as industrial agriculture or factory farming).', 'none', 0, false),
    (34681, 'Melvin Goes to Dinner', 2003, '/nH2RvmUq4c2R4GN4GRzlVV3dHMx.jpg', '{18,35,10749}', 'Four thirtysomethings convene for a wine-fueled dinner party that turns increasingly intimate as they discuss everything from religion and ghosts to relationships and sexual fetishes.', 'none', 0, false),
    (10305, 'Nightcap', 2000, '/76tPsLIYj9OYoZNFTXWridt7psC.jpg', '{18,53,9648}', 'Mika, heiress to a Swiss chocolate company, is married to celebrated pianist André and stepmother to his son, Guillaume, whose mother died in a car wreck on his tenth birthday. Their lives are interrupted by the unexpected arrival of Jeanne, a young woman who has learned she was almost switched with Guillaume at birth.', 'none', 0, false),
    (48121, 'Mondovino', 2004, '/ciXRSY7ScGESKXx40llMb4IMUsE.jpg', '{99}', 'Mondovino (in Italian: World of Wine) is a documentary film on the impact of globalization on the world''s different wine regions written and directed by American film maker Jonathan Nossiter. It was nominated for the Palme d''Or at the 2004 Cannes Film Festival and a César Award. The film explores the impact of globalization on the various wine-producing regions, and the influence of critics like Robert Parker and consultants like Michel Rolland in defining an international style. It pits the ambitions of large, multinational wine producers, in particular Robert Mondavi, against the small, single estate wineries who have traditionally boasted wines with individual character driven by their terroir.', 'none', 0, false),
    (497052, 'Monsieur Albert', 1976, '/hit8oh9LwSVQjM7nvDLj01fy2bS.jpg', '{}', 'In this poetic slice-of-life film that reveals the problems and needs of a group of lowlife characters, unwed mother Vivaine (Dominique Labourier) falls in love with working-class youth Francois (Patrick Chesnais) who has a shady past. Albert (Philippe Noiret), a no-good insurance con-artist, poses for many years as Francois'' friend, but tragedy ensues when Albert comes between the lovers, and Francois and Albert resort to physical violence to settle their differences.', 'none', 0, false),
    (3640, 'Mostly Martha', 2001, '/gnmIUzqZ8YW5i0QolN5P2dsiRT0.jpg', '{18,35,10749}', 'Martha is a single woman who lives for one passion: cooking. The head chef at a chic restaurant, Martha has no time for anything - or anyone - else. But Martha''s solitary life is shaken when a fateful accident brings her sister''s eight-year-old daughter, Lina, to her doorstep.', 'none', 4160475, false),
    (63624, 'My Breakfast with Blassie', 1983, '/igTeW7rDxDISU8ysoEW7rgIUYc1.jpg', '{35}', 'My Breakfast with Blassie is a movie starring Andy Kaufman and professional wrestler "Classy" Freddie Blassie. It is a mostly improvised parody of the popular art film My Dinner with Andre and is set in a restaurant where Kaufman and Blassie have a discussion over breakfast. Also featured is Kaufman''s partner Bob Zmuda, who plays a nosy fan. Lynne Margulies, who would later become Kaufman''s girlfriend, also plays a role; in fact, she and Kaufman met for the first time on camera.', 'none', 0, false),
    (25468, 'My Dinner with Andre', 1981, '/lakuk8UpDUBrO5c8uoWbKxy5j0e.jpg', '{18,35}', 'Wally, a struggling playwright and actor, reluctantly agrees to catch up with his old friend Andre, a theater director who disappeared several years prior in order to travel the world. Meeting at a posh Manhattan restaurant, the two share life stories, anecdotes and philosophical musings over the course of an evening meal.', 'none', 5250000, false),
    (11191, 'Mystic Pizza', 1988, '/2wqMKLJEMjenT7U8UqnuI070cUC.jpg', '{18,35,10749}', 'Three teenage girls come of age while working at a pizza parlor in Mystic, Connecticut.', 'none', 12793213, false),
    (3638, 'No Reservations', 2007, '/eKqfRSf0DZ0Qey1f9ZHuZfsmXVR.jpg', '{18,35,10749}', 'Master chef Kate Armstrong runs her life and her kitchen with intimidating intensity. However, a recipe for disaster may be in the works when she becomes the guardian of her young niece while crossing forks with the brash sous-chef who just joined her staff. Though romance blooms in the face of rivalry, Kate needs to look outside the kitchen to find true happiness.', 'none', 92601050, false),
    (99509, 'Now, Forager', 2012, '/eIFUdjrJmTbVHlUdFyZq7vCdWHr.jpg', '{18}', 'Lucien and Regina are foragers - they gather wild mushrooms and sell them to New York restaurants. They live simply, according to the seasons. When Regina seeks more stability, their marriage is put to a test.', 'none', 0, false),
    (85984, 'Off the Menu: The Last Days of Chasen''s', 1998, '/4QSZ1oUfQQvgUcDUlAhJACEGDhw.jpg', '{18,99}', 'In 1995, Chasen''s closed its doors after 60 years of serving chili to movie stars and visiting dignitaries, Presidents and the Pope. During its two final weeks, Chasen regulars (actors and producers), staff, and management sat for interviews. There''s an Oscar party for 1500, footage and photos of famous diners, and time with Tommy Gallagher, the ebullient head waiter until retirement in 1994, his son Patrick, catering head Raymond Bilbool, general manager Ronnie Clint, hat check girl Val Schwab, ladies'' room attendant Onetta Johnson, and foreign- born waiters, including Jaime. When he started in 1970, like other Latins, he wasn''t allowed out of the kitchen. It''s a family farewell.', 'none', 0, false),
    (195186, 'Comic Face', NULL, '/qYDKhQ2T7oEzlUvOyPDYkkNCCno.jpg', '{}', 'An old man gets progressively livelier - and drunker - as he downs his bottle of beer. Finally, he cocks a snook - and doesn''t bother to uncock it as he continues to drink.', 'none', 0, false),
    (430, 'One, Two, Three', 1961, '/yWQE227ub1frfnjP5HZy0wLF0wu.jpg', '{35}', 'In Cold War-era West Berlin, American Coca-Cola executive C.R. ''Mac'' MacNamara is tasked with playing babysitter to his boss'' spoiled 17-year-old daughter Scarlett, who proves more difficult than anticipated when she reveals that she is pregnant by a Communist.', 'nominee', 4000000, false),
    (72435, 'Osaka Wrestling Restaurant', 2004, '/lNeYQfVcGStjCKYg3vdZuJ5HKuQ.jpg', '{28,35}', 'Ricky aspires to be a famous chef. But rival restauranteur Dragon wants him to fail. So when Ricky''s brother suggests that he combine Osaka wrestling with Hong Kong cuisine, his restaurant strikes gold and wins rave reviews, but Dragon swears revenge. Overview: Ricky is a canteen handyman, his goal was to be a famous chef. His boss, One-Eye Dragon, was really mean to him and wanted to kill Ricky. Ricky went to Osaka and looked for his brother Mike. Mike suggested that he wanted to match up Osaka wrestling with the food from Hong Kong. And Mike taught in person the techniques of Osaka wrestling. Famous eating expert Chau visited the restaurant. Mike made the steamed dumpling for Chau to taste and was highly praised. The steamed dumpling attracted all the older customer and the business boomed again. But jeopardy rose! Dragon decided to "do it all", and brought a time bomb into the restaurant...', 'none', 0, false),
    (37221, 'Another Egg and Chicken Movie', 2009, '/c7LMN9NrJQ97RxYM33qu5ItcbCn.jpg', '{12,16,35,10751}', 'Toto, now a chicken, tries to live as such, while Willy and Bibi deal some problems between them. A sorcerer egg desert needs a chicken heart to cast a spell. He sends his armies of eggs vulture, ostrich and scorpion to kidnap Toto. His friends embark on a journey through the desert to rescue the chicken, where they live countless adventures', 'none', 8583678, true),
    (24565, 'Our Daily Bread', 2005, '/kdW7HPJqhRQ2HRU9ZurbDbpTyj.jpg', '{99}', 'Welcome to the world of industrial food production and high-tech farming! To the rhythm of conveyor belts and immense machines, the film looks without commenting into the places where food is produced in Europe: monumental spaces, surreal landscapes and bizarre sounds - a cool, industrial environment which leaves little space for individualism.', 'none', 0, false),
    (7518, 'Over the Hedge', 2006, '/jtZnymorbnHY7mOiBXR14ZDJseM.jpg', '{12,16,35,10751}', 'A scheming raccoon fools a mismatched family of forest creatures into helping him repay a debt of food, by invading the new suburban sprawl that popped up while they were hibernating – and learns a lesson about family himself.', 'none', 343397247, false),
    (758033, 'Paavo, a Life in Five Courses', 2010, '/9o3REC89XNYqj2PH7OhLfJ4j0Zj.jpg', '{99}', 'Finnish farm boy Paavo Turtiainen is hired into the Parisian household of Swedish theatre producer Lars Schmidt and his wife, actress Ingrid Bergman. The couple “adopt” and train Paavo to navigate among the rich and famous. Later on, Paavo becomes the personal secretary for Schmidt and Bergman. His responsibilities include building up the personal archives of both Schmidt and Bergman. Ms. Bergman’s archives are now at the film archives of Wesleyan University and Schmidt’s archives are in the United States Library of Congress. After Schmidt and Bergman divorce Paavo decides to settle permanently in New York. His first clients are friends of Schmidt: celebrities and business personalities Paavo has met while working in Paris and on Dannholmen, a Swedish island owned by Schmidt. Eventually Paavo becomes an acclaimed chef and event planner for high society. Along the way, he has learned to stand on his own feet.', 'none', 0, false),
    (80710, 'Patisserie Coin De Rue', 2011, '/duYnytjXcdyQI1q7UjEpS3ystPa.jpg', '{18}', 'A disillusioned Natsume arrives at Coin de Rue, a popular Tokyo pastry shop, begging for work. Aiming to become a high-calibre pastry chef, she is determined to overcome both her past and the challenges ahead.  Pastry critic Tomura is a frequent visitor to Coin de Rue. Moved by Natsume''s persistence, he slowly begins to confront his own painful past aided, of course, by mouthfuls of tasty pastries.', 'none', 0, false),
    (340714, 'Peaceable Kingdom', 2004, '/hGAOO734DaBPTLheeuFx5dmmHWW.jpg', '{99}', 'At a time when the public is more concerned than ever about the health and environmental problems associated with large-scale factory farming, Peaceable Kingdom explores another angle of this unfolding story: the interconnected life journeys of farm animals, former farmers, and animal rescuers struggling against an out of control industrial system.  Breaking generations of silence in the farm community, Peaceable Kingdom weaves together themes of respect, forgiveness, commitment, and healing, offering a vision of a more peaceful world that is well within our reach.', 'none', 0, false),
    (832752, 'Pennsylvania Diners and Other Roadside Restaurants', 1993, '/6t92WTqYJzLIcRVUmmuV79Lvi8E.jpg', '{99}', 'In an age when every fast food place seems the same, diners have remained distinctive, fun places to stop, full of local flavor. This program takes a look at several of the most interesting diners in Pennsylvania, and also considers a few other roadside restaurants (like Midway Plaza on the Pennsylvania Turnpike) that have interesting histories and reputations for good “home-cooked” food. So get a cup of coffee. Have a seat. And come along as we visit great little restaurants from Wellsboro to Downingtown, from Milford to Conneaut Lake. Let’s go to Potato City, to the Melrose in Philly and to unforgettable little places from Pittsburgh to Poconos. Whether it’s the middle of the night in State College or lunchtime in Smethport, this documentary gives you an unusual taste of Pennsylvania and some of its quirkier cuisine.', 'none', 0, false),
    (51999, 'Perfect Sense', 2011, '/2UuuO6MX1AzD61zX6NHiHQODoI1.jpg', '{18,10749}', 'In Glasgow, Scotland, while a mysterious pandemic begins to spread around the world, Susan, a brilliant epidemiologist, falls in love with Michael, a skillful cook.', 'none', 138868, false),
    (1550, 'Pieces of April', 2003, '/qm3jGZwz2UkwwEFEFzSot8T0pz1.jpg', '{18,35}', 'Quirky and rebellious April Burns lives with her boyfriend in a low-rent New York City apartment miles away from her emotionally distant family. But when she discovers that her mother has a fatal form of breast cancer, she invites the clan to her place for Thanksgiving. While her father struggles to drive her family into the city, April -- an inexperienced cook -- runs into kitchen trouble and must ask a neighbor for help.', 'nominee', 0, false),
    (124709, 'Planeat', 2010, '/jnhY08LX32lNxVg04KDIcZ2dO54.jpg', '{99}', 'The story of three men''s life-long search for a diet which is good for our health, the environment and the future of our planet - showcasing some of the best food you have ever seen.', 'none', 0, false),
    (230671, 'Porky''s Last Stand', 1940, '/am5xUAbl7bYlUKqWLEc1lDreBe2.jpg', '{16,35}', 'Porky and Daffy run a diner. The eggs come from chickens kept on the premises. A customer orders a hamburger, and Daffy discovers the mice have gotten to the meat first and left a note. He spots a calf outside and goes after it but ends up having to fight off a large bull. Meanwhile, Porky is preparing an order of two eggs, but one of them is actually a baby chick, who runs away. Daffy manages to sic the bull on Porky, who does some acrobatics to escape until Daffy lures the bull back to him. The bull finally crashes into the diner.', 'none', 0, false),
    (2062, 'Ratatouille', 2007, '/t3vaWRPSf6WjDSamIkKDs1iQWna.jpg', '{14,16,35,10751}', 'In one of Paris''s finest restaurants, Remy, a determined young rat, dreams of becoming a renowned French chef. Torn between his family''s wishes and his true calling, Remy and his pal Linguini set in motion a hilarious chain of events that turns the City of Lights upside down.', 'winner', 623726000, false),
    (174358, 'Red Obsession', 2013, '/3345e6iaHJBx4mrIKoJ4f3gzHwH.jpg', '{36,99}', 'France’s Bordeaux region has long commanded respect for its coveted wine, but shifts in the global marketplace mean that a new, voracious consumer base in China is buying up this finite product. Bordeaux both struggles with and courts the spike in demand, sending prices skyrocketing. Narrated by Russell Crowe, Red Obsession is a fascinating look at our changing international economy and how an obsession in Shanghai affects the most illustrious vineyards in France.', 'none', 0, false),
    (15482, 'Return of the Killer Tomatoes!', 1988, '/gO6mxCEMcyP6teOQb32Yvq9ERCA.jpg', '{27,35}', 'Crazy old Professor Gangreen has developed a way to make tomatoes look human for a second invasion.', 'none', 5000000, true),
    (358725, 'Saint Amour', 2016, '/A9wTBWnx6nKitul3vjKHrRKjWRk.jpg', '{18,35}', 'Every year, Bruno makes a tour of all the wine stands, without setting foot outside the Show’s premises and without ever finishing his wine trail. This year, his father suggests they finish it together, but a real wine trail, across the French countryside. Accompanied by Mike, a young, quirky taxi driver, they set off in the direction of France’s major wine regions. Together, they are going to discover not only the wine trails, but also the road that leads back to Love.', 'none', 0, false),
    (15084, 'Salaam Namaste', 2005, '/wL1lm92Da9R7VEPXD0ZCSt1kuUd.jpg', '{18,35,10749}', 'Two young Indian expatriates in Melbourne, Australia, Nick, a chef and radio host Ambar, who decide to live together without marriage, leading to conflict and unexpected parenthood when Ambar gets pregnant.', 'none', 0, false),
    (223702, 'Sausage Party', 2016, '/vNgdPJQ5CI60oEiiHLKRNrsDhMy.jpg', '{12,14,16,35}', 'Hot dog Frank leads a group of supermarket products on a quest to discover the truth about their existence and what really happens when they''re chosen to leave the grocery store.', 'none', 140705322, false),
    (144886, 'Schwechater', 1958, '/lFZNrbNn9Sken5t6kIS2fb02N8i.jpg', '{}', 'In 1957, Peter Kubelka was hired to make a short commercial for Schwechater beer. The beer company undoubtedly thought they were commissioning a film that would help them sell their beers; Kubelka had other ideas. He shot his film with a camera that did not even have a viewer, simply pointing it in the general direction of the action. He then took many months to edit his footage, while the company fumed and demanded a finished product. Finally he submitted a film, 90 seconds long, that featured extremely rapid cutting (cutting at the limits of most viewers'' perception) between images washed out almost to the point of abstraction — in black-and-white positive and negative and with red tint — of dimly visible people drinking beer and of the froth of beer seen in a fully abstract pattern.', 'none', 0, false),
    (423720, 'Service for Ladies', 1927, NULL, '{35}', 'Albert Leroux, headwaiter at an exclusive Paris hotel, falls hopelessly in love with Elizabeth Foster, an American heiress, though he is convinced that she will never admire a waiter.', 'none', 0, false),
    (264422, 'Service for Ladies', 1932, '/9UeFlT907fehY9KBxFHzCJAFoBs.jpg', '{35,10749}', 'Max Tracey is the head waiter at a London hotel. He falls in love at first sight with Sylvia Robertson, an aristocratic woman, and poses as a prince to win her love. In this venture, he is aided by Mr. Westlake, a Ruritanian monarch who owes him a favour. When Sylvia discovers Max''s deception, she is appalled, but the situation is resolved when her father tells her that he was once a hotel dishwasher.', 'none', 0, false),
    (9675, 'Sideways', 2004, '/zOsaxYLgvZVU7cJBpPn8CuE0MrP.jpg', '{18,35,10749}', 'Two middle-aged men embark on a spiritual journey through Californian wine country. One is an unpublished novelist suffering from depression, and the other is only days away from walking down the aisle.', 'winner', 109502303, false),
    (128169, 'Sideways', 2009, '/vtZO9yJEkX7DJ18aLA93cPbygK3.jpg', '{35,10749}', 'A struggling writer and his engaged buddy hit the road for California wine country.', 'none', 0, false),
    (16172, 'Simply Irresistible', 1999, '/zFsqqPQUz69wPaLBqQeiGbGiW7J.jpg', '{35,10749}', 'After her mother''s death, mediocre chef Amanda Shelton is having trouble attracting customers to her family''s restaurant. While shopping for ingredients, she is given a magical crab by mysterious Gene O''Reilly. Afterward, Amanda''s dishes suddenly become excellent, inducing strong emotional reactions in everyone who eats them. Tom Bartlett, who is preparing to open his own eatery, tries her cooking and falls in love.', 'none', 4398989, false),
    (11006, 'Smokey and the Bandit', 1977, '/w4RqNZtVHB5Uzlnl6zQlMHft7QI.jpg', '{12,28,35}', 'A race car driver tries to transport an illegal beer shipment from Texas to Atlanta in under 28 hours, picking up a reluctant bride-to-be on the way.', 'nominee', 126700000, false),
    (184149, 'Somm', 2012, '/AusSOmDe3jMrXeTn0YosX1Ezai7.jpg', '{99}', 'Somm takes the viewer on a humorous, emotional and illuminating look into the mysterious world of the Court of Master Sommeliers and their massively intimidating Master Sommelier Exam.', 'none', 0, false),
    (549321, 'Somm III', 2018, '/rrPKRc4Zyc1FiEdocdGgQjgYHYC.jpg', '{99}', 'Three legends in the world of wine—Fred Dame, Steven Spurrier and Jancis Robinson—sit down in Paris to taste the rarest bottles of their careers. Dustin Wilson gathers the greatest blind tasters of today in New York City for a secret tasting similar to the original Judgment of Paris, with the goal to see if any of the world’s Pinot Noirs can stand up to the greatest Burgundies of France. In the end, both tastings cross with results that could change the world of wine forever.', 'none', 0, true),
    (372315, 'Somm: Into the Bottle', 2015, '/6Qi5BbPfz5TgvT5TqHxm32wUbx0.jpg', '{99}', 'The curtain is raised into the seldom seen world that surrounds the wine we drink. How many people understand how wine is produced? How it is grown? What goes on in the cellar? From those questions to how many hands touch a bottle, to why wine costs what it costs, to how certain wines end up on a wine list, this is a never before seen look into the world of wine.', 'none', 0, true),
    (391659, 'Song of the Eagle', 1933, '/7XtAQkAQkb81ZHbKrELdvqpe2Ea.jpg', '{18,80}', 'This drama centers on the fight for certain post-Prohibitionist groups to gain total control over the liquor industry. Much of the tale is focused upon a family endeavoring to keep their little brewery.', 'none', 0, false),
    (29461, 'Soul Food', 1997, '/97t6YjxjTpwQ439MJcPiPDrMAg0.jpg', '{18,35}', 'Traditional Sunday dinners at Mama Joe''s turn sour when sisters Teri, Bird and Maxine start bringing their problems to the dinner table in this ensemble comedy. When tragedy strikes, it''s up to grandson Ahmad to pull the family together and put the soul back into the family''s weekly gatherings.', 'none', 0, false),
    (247053, 'Soul Food Junkies', 2012, '/7tZIlvPZJTBe1Tk7i9belwttA3r.jpg', '{99}', 'To many African Americans, soul food is sacrament, ritual, and a key expression of cultural identity. But does this traditional cuisine do more harm to health than it soothes the soul?', 'none', 0, false),
    (31175, 'Soul Kitchen', 2009, '/9Y2OQ7MFouzmVCMqqvZPLrzHF0F.jpg', '{18,35}', 'In Hamburg, German-Greek chef Zinos unknowingly disturbs the peace in his locals-only restaurant by hiring a more talented chef.', 'none', 18164139, false),
    (396232, 'Sour Grapes', 2016, '/8jLfS18TvzQ4IkpMXHIgWgS8kZW.jpg', '{99}', 'Controversy erupts when an unassuming young man floods the American wine market with fake vintages valued in the millions, bamboozling the wine world elite, in this humorous and suspenseful tale of an ingenious con on the eve of the 2008 stock market crash.', 'none', 0, false),
    (12101, 'Soylent Green', 1973, '/5nbkShkOEXUoKVhaX0XG41wyBkq.jpg', '{80,9648}', 'In the year 2022, overcrowding, pollution,  and resource depletion have reduced society’s leaders to finding food for the teeming masses. The answer is Soylent Green.', 'none', 3600000, false),
    (1216960, 'Spin', 2021, '/7nFG78Hg8GkuPrDnLi8XUTLUXE.jpg', '{18}', 'An anxious Catherine is unable to communicate with her five year old daughter. Can she discover a new way to connect to her at a busy casino party?', 'none', 0, false),
    (270125, 'State of Bacon', 2014, '/oAiaYaOXBwEzpCoErSam8SO6zwi.jpg', '{35,99}', 'State of Bacon tells the kinda real but mostly fake tale of an oddball group of characters leading up to the annual Blue Ribbon Bacon Festival. Bacon-enthusiasts, Governor Branstad, a bacon queen, Hacksaw Jim Duggan, members of PETA, and an envoy of Icelanders are not excluded from this bacon party and during the course of the film become intertwined with the organizers of the festival to show that bacon diplomacy is not dead.', 'none', 0, false),
    (15105, 'Still Waiting...', 2009, '/kyZd2qJm5lrIM3VxaTp1oDBm0VC.jpg', '{35}', 'After Shenaniganz loses all its hottest waitresses to new competitor Ta-Ta''s Wing Shack -- where the scantily clad wait staff earns bigger tips -- the Shenaniganz staff aims to give Ta-Ta''s its just desserts.', 'none', 0, true),
    (12921, 'Strange Brew', 1983, '/rScplcvRHX7o7XK88SFb5mddo8y.jpg', '{35,80}', 'Something is rotten at the Elsinore Brewery. Bob and Doug McKenzie (as seen on SCTV) help the orphan Pam regain the brewery founded by her recently-deceased father. But to do so, they must confront the suspicious Brewmeister Smith and two teams of vicious hockey players.', 'none', 1913389, false),
    (33447, 'Summer in Tyrol', 1964, '/qGl1wNkLw75mNajfH73KSpJtCWw.jpg', '{35,10402,10751}', 'At the Gästhaus "Den Hvide Hest" in the Austrian Alps, romantic entanglements are in full swing. Waiter Leopold is in love with landlady Josepha, who has her eye on charming manufacturer Sigismund, who in turn hits on all women almost as a matter of principle. Klara and Lene also join the battle for the popular manufacturer, while waiter apprentice Mickey would rather just have a goat.', 'none', 0, false),
    (9372, 'Super Size Me', 2004, '/zYkbqQaCuIHBxqBDGgnQCwJ9jIG.jpg', '{99}', 'Morgan Spurlock subjects himself to a diet based only on McDonald''s fast food three times a day for thirty days without exercising to try to prove why so many Americans are fat or obese. He submits himself to a complete check-up by three doctors, comparing his weight along the way, resulting in a scary conclusion.', 'nominee', 28575078, false),
    (468996, 'Super Size Me 2: Holy Chicken!', 2017, '/bq1RcG7UPEzyq63Gi8S59h50Z3X.jpg', '{99}', 'Muckraking filmmaker Morgan Spurlock reignites his battle with the food industry — this time from behind the register — as he opens his own fast food restaurant.', 'none', 0, true),
    (319373, 'Sweet Bean', 2015, '/5YV0eoUBFQ4vKaN71SPtUte2YcD.jpg', '{18}', 'The master of a dorayaki pastry store hires a 76-year-old woman whose talents attract customers from all over. But she''s hiding a troubling secret. Life''s joys are found in the little details, and no matter what may be weighing you down, everyone loves a good pastry.', 'none', 124518, false),
    (42371, 'Take This Job and Shove It', 1981, '/rAlLrcOr1ZSjXXIP1yY3FcXyLBZ.jpg', '{35,10749}', 'A junior executive is ordered to boost output in the hometown brewery where his old friends work.', 'none', 0, false),
    (11830, 'Tampopo', 1985, '/ArYdSuX3zY9fMsE4LqmBl7xJq5R.jpg', '{35}', 'In this humorous paean to the joys of food, a pair of truck drivers happen onto a decrepit roadside shop selling ramen noodles. The widowed owner, Tampopo, begs them to help her turn her establishment into a paragon of the "art of noodle-soup making". Interspersed are satirical vignettes about the importance of food to different aspects of human life.', 'none', 0, false),
    (112274, 'Terminal Bar', 2003, '/49UbY86z51mtDQer1MtdxZU0Wnd.jpg', '{99}', 'A fascinating pictorial history of a New York City bar whose customers, from the hard-drinking working class Irish to the coiffed African American gay male, continually transform its focus during its 10-year reign.', 'none', 0, false),
    (103747, 'The Angels'' Share', 2012, '/bt9kJ8gwTMaDcmL0INlJYIZ887t.jpg', '{18,35}', 'Robbie is a Glasgow boy locked in a family feud who just wants a way out. On community service, he meets Rhino, Albert and Mo. Little did Robbie imagine that turning to drink might change their lives, leading them to the distilleries of the Scottish Highlands and the biggest gamble of his life.', 'none', 13090471, false),
    (47856, 'The Attack of the Giant Mousaka', 1999, '/rnAcMnGh1ehG8rPHjDQe5wVJnmW.jpg', '{35}', 'Around the year 2000, a terrible occurence shocks the city of Athens: a huge piece of moussaka appears on the city streets, spreading panic and death. Everyone keeps wondering: why, where, how, for what reason? But no one can give an answer...', 'none', 0, false),
    (328594, 'The Birth of Saké', 2015, '/2kzKjSvC3t3pRS14WUkKi1ne4Il.jpg', '{36,99}', 'Through the unrelenting winter in the north of Japan, a small group of workers must brave unusual working conditions to bring to life a 2,000-year-old tradition known as sake. A cinematic documentary, The Birth of Sake is a visually immersive experience of an almost-secret world in which large sacrifices must be made for the survival of a time-honored brew.', 'none', 0, false),
    (504827, 'The Bob''s Burgers Movie', 2022, '/AvV2nHEDQMWuRqAUrpcx2fB97CB.jpg', '{16,35,80,9648}', 'When a ruptured water main creates an enormous sinkhole right in front of Bob''s Burgers, it blocks the entrance indefinitely and ruins the Belchers’ plans for a successful summer. While Bob and Linda struggle to keep the business afloat, the kids try to solve a mystery that could save their family''s restaurant. As the dangers mount, these underdogs help each other find hope and fight to get back behind the counter, where they belong.', 'none', 34148750, false),
    (464825, 'The Cakemaker', 2017, '/WwHLnuqqwhvCkBACCMAR5xuQMA.jpg', '{18}', 'Thomas, a young German baker, is having an affair with Oren, an Israeli married man who has frequent business visits in Berlin. When Oren dies in a car crash in Israel, Thomas travels to Jerusalem seeking for answers regarding his death. Under a fabricated identity, Thomas infiltrates the life of Anat, his lover’s newly widowed wife, who owns a small Café in downtown Jerusalem. Thomas starts to work for her, creating German cakes and cookies that bring her Café to life. Thomas finds himself involved in Anat’s life in a way far beyond his anticipation. To protect the truth he will stretch his lie to a point of no return.', 'none', 0, false),
    (85872, 'Le Chef', 2012, '/752BCNz9uFiym29bqIsyOaPAln5.jpg', '{35}', 'A veteran chef faces off against his restaurant group''s new CEO, who wants to the establishment to lose a star from its rating in order to bring in a younger chef who specializes in molecular gastronomy.', 'none', 306724, false),
    (93465, 'The Chinese Feast', 1995, '/hbal71oj7AlzQSlvUeAMXHFM1rz.jpg', '{35,10749}', 'Within a few years, petty crook Chiu rises to gang leader. But his professional ambitions are actually quite different: he wants to leave illegality behind and make a career for himself and his lover in Canada... as a chef. However, this craft must first be learned and Chiu''s talent in the field of cooking leaves much to be desired.', 'none', 0, false),
    (42048, 'The Coca-Cola Kid', 1985, '/yBfZ52KgC3gnt8UrBULVRp43liC.jpg', '{18,35,10749}', 'An eccentric marketing guru visits a Coca-Cola subsidiary in Australia to try and increase market penetration. He finds zero penetration in a valley owned by an old man who makes his own soft drinks, and visits the valley to see why. After "the Kid''s" persistence is tested he''s given a tour of the man''s plant, and they begin talking of a joint venture. Things get more complicated when the Coca-Cola man begins falling in love with his temporary secretary, who seems to have connections to the valley.', 'none', 0, false),
    (153809, 'The Cola Conquest', 1998, '/sdpclb190Dy86THmcKOGspp55xC.jpg', '{99}', 'The story of Coca-Cola -- the ''sublimated essence'' of all that American stands for -- and the century-long competition with its rival, Pepsi-Cola. Challenging, fast-paced, irreverent, serious and funny by turns, it explores the delicious paradox at the heart of Coke: How did an innocuous soft drink come to wield such enormous power and assume such significance in so many people''s lives? What does it tell us about who we are and what we are becoming?', 'none', 0, false),
    (7452, 'The Cook, the Thief, His Wife & Her Lover', 1989, '/15xMqAnFsROopAT66zdRyu2Dtek.jpg', '{18,80}', 'When churlish mobster Albert Spica acquires an upscale French restaurant in London, he dines there nightly, effectively scaring off the clientele with his bad manners. His wife, Georgina, is especially disgusted by him, and soon begins an affair with regular guest Michael. Despite their best efforts to keep it secret, Spica learns about their trysts, and he plots a terrible revenge.', 'none', 7724701, false),
    (401546, 'The Dinner', 2017, '/8rhlkQo3fqPlC9MH8wOHCu4XQjN.jpg', '{18,53,9648}', 'Two brothers and their wives meet up at a haute-cuisine restaurant to discuss what to do about a horrific crime that their sons committed together. As the quartet debate their options, the conversation reopens old wounds between the siblings.', 'none', 2500000, false),
    (144432, 'The Enchanted Drawing', NULL, '/9YNuIXEj3gpItJCNYR3txzNV4fl.jpg', '{14,16,35}', 'A cartoonist defies reality when he draws objects that become three-dimensional after he lifts them off his sketch pad.', 'none', 0, false),
    (63348, 'The Encounter', 2010, '/o40841LWnE4xhldkjqUaznZFIYx.jpg', '{18,10751}', 'When five strangers with nothing in common come together at a remote roadside eatery, they place their orders with the diner''s omniscient owner, who seems to know everything about them ... and is eerily reminiscent of Jesus Christ.', 'none', 0, false),
    (304571, 'The Fight with the Dragon', 1935, '/7iEu5IWfVO8fTTvloZEwzN0sM1y.jpg', '{35}', 'Countess von Drachenstein, owner of the traditional Drachenstein Castle Brewery, where the famous Drachenbräu beer has been brewed for 300 years, stubbornly refuses to agree to a merger between the Drachen and Sonnen breweries. Trude, the niece, and Fritz, the son of the manager of the Sonnenbrauerei, try in vain to poach Bachmeier, the master brewer at the Drachenbrauerei. But then Trude falls in love with Bachmeier, and Fritz with Countess Helene, the niece of the Countess von Drachenstein. And so the family businesses end up merging after all.', 'none', 0, false),
    (12456, 'The Five Obstructions', 2003, '/xMcCmIdos88yd44xqCXj4NUWph3.jpg', '{99}', 'In 1967, experimental filmmaker Jorgen Leth created a striking short film, The Perfect Human, starring a man and women sitting in a box while a narrator poses questions about their relationship and humanity. Years later, Danish director Lars von Trier made a deal with Leth to remake his film five times, each under a different set of circumstances and with von Trier''s strictly prescribed rules. As Leth completes each challenge, von Trier creates increasingly further elaborate stipulations.', 'none', 279032, false),
    (310307, 'The Founder', 2016, '/8gLIksu5ggdfBL1UbeTeonHquxl.jpg', '{18,36}', 'The true story of how Ray Kroc, a salesman from Illinois, met Mac and Dick McDonald, who were running a burger operation in 1950s Southern California. Kroc was impressed by the brothers’ speedy system of making the food and saw franchise potential. He maneuvered himself into a position to be able to pull the company from the brothers and create a billion-dollar empire.', 'none', 24121245, false),
    (142121, 'A Beer Tale', 2012, '/gPz8TK2cFYrBKxWVpRMNDDnq6EH.jpg', '{35,10749}', 'A coming of age romantic comedy centered around the lives of twin brothers Luke and Corey Frankenstein in the pivotal months following college graduation. Orphaned at the age of five, the brothers inherited their family brewery and were left in the care of their uncle, a well-meaning but less than ideal paternal figure. Raised on beer, with the assumption they''re all grown up, Luke and Corey decide it''s time to finish their family beer; a beer their parents started but were never able to finish twenty years ago. But when the idealistic Luke meets a girl whose family shows him the home life he''s always wanted, he abandons Corey and their family beer in pursuit of this budding relationship. Corey, however, refuses to go down without a fight, and the ensuing mayhem that follows pits brother against brother and forces the Colorado wild boys to finally grow up and decide what kind of men they really want to be.', 'none', 0, false),
    (128766, 'The Fruit Hunters', 2012, '/c1vttkJx0I6231WIH0MJIuQbSi1.jpg', '{99}', 'The Fruit Hunters explores the little known subculture and history of rare fruit hunters who travel the globe in an obsessive search for the exotic, in this stylish and sometimes erotic documentary.', 'none', 0, false),
    (41343, 'The God of Cookery', 1996, '/9BbEsmLl1kVPcsojW5W8kMm5Ws5.jpg', '{14,18,35}', 'The most renowned and feared chef in the world loses his title of God of Cookery because of his pompous attitude. Humbled, he sets out to reclaim his title.', 'none', 0, false),
    (305753, 'The God of Ramen', 2013, '/eB9KLtKb0Xf2BhttNBCTy5y4OgQ.jpg', '{99}', 'Every day, people would queue for over two hours for a bowl of ramen. What’s the celebrated chef’s secret ingredient? There is no secret ingredient. In fact, as most fans of Taishoken believe, it’s the charisma of owner Kazuo Yamagishi that attracted people from all around Japan to his modest shop. His personality and love for his craft, combined with a precise mélange of flavours, combined to create perfection in each ramen bowl. This heart-warming documentary is not just for noodle fans, but for anyone who loves to be inspired by passionate people.', 'none', 0, false),
    (8393, 'The Gods Must Be Crazy', 1980, '/wntGWN2mpeS3QaUm1PTKAcTM9K7.jpg', '{28,35}', 'A Coca-Cola bottle dropped from an airplane raises havoc among a normally peaceful tribe of African bushmen who believe it to be a utensil of the gods.', 'none', 200000000, false),
    (228194, 'The Hundred-Foot Journey', 2014, '/1vFhSr7INoulu18smHqicft05i8.jpg', '{18,35}', 'A story centered around an Indian family who moves to France and opens a restaurant across the street from a Michelin-starred French restaurant.', 'none', 89500000, false),
    (267481, 'Kitchen in Paris', 2014, '/gB0bjZZULhS4sj234nF6zJyUaD3.jpg', '{35,10749}', 'A restaurant in Moscow is forced to shut shop after they end up ruining a crucial political dinner involving the president. The entire team then decides to relocate to Paris to redeem themselves.', 'none', 13969785, false),
    (593643, 'The Menu', 2022, '/fPtUgMcLIboqlTlPrq0bQpKK8eq.jpg', '{27,35}', 'A young couple travels to a remote island to eat at an exclusive restaurant where the chef has prepared a lavish menu, with some shocking surprises.', 'none', 79628200, false),
    (212088, 'The Nuttiest Nutcracker', 1999, '/w32qMVzC5A0YlWXBYAfB6wWAACJ.jpg', '{12,14,16,10402,10751}', 'A group of fruit and vegetables try to help the Nutcracker''s army get a star up on a Christmas tree before midnight, and stop a rodent army from destroying Christmas.', 'none', 0, false),
    (429199, 'The Other Side of Hope', 2017, '/spqAX6L4YtPaCj2dnc10Tku9AU7.jpg', '{18,35}', 'A restaurateur befriends a Syrian refugee who  has recently arrived in Finland.', 'none', 1657449, false),
    (17030, 'The Petrified Forest', 1936, '/kjE4pw6mqoA1OJHNLq1aol4y4C1.jpg', '{18,53,80,10749}', 'Gabby, the waitress in an isolated Arizona diner, dreams of a bigger and better life. One day penniless intellectual Alan drifts into the joint and the two strike up a rapport. Soon enough, notorious killer Duke Mantee takes the diner''s inhabitants hostage. Surrounded by miles of desert, the patrons and staff are forced to sit tight with Mantee and his gang overnight.', 'none', 0, false),
    (619264, 'The Platform', 2019, '/iXvQnzy6JCAx1PiQEKXuTY04ZHl.jpg', '{18,53}', 'A slab of food descends down a vertical facility. The residents above eat heartily, leaving those below starving and desperate. A rebellion is imminent.', 'none', 1090116, false),
    (10198, 'The Princess and the Frog', 2009, '/yprv5PbnEksoVj2v6XEnDBg9joR.jpg', '{14,16,10749,10751}', 'A waitress, desperate to fulfill her dreams as a restaurant owner, is set on a journey to turn a frog prince back into a human being, but she has to face the same problem after she kisses him.', 'nominee', 270997378, false),
    (18585, 'The Ramen Girl', 2008, '/616tXSqbAVRbeQKV0IeWf0kNnqi.jpg', '{18,35,10749}', 'An American woman is stranded in Tokyo after breaking up with her boyfriend. Searching for direction in life, she trains to be a ramen chef under a tyrannical Japanese master.', 'none', 179590, false),
    (1346491, 'The Scarecrow', 2013, '/f6xIHo60ARHBWSYA4BcIBnBoztE.jpg', '{16,18}', 'The story of an overworked Scarecrow, that decides to save the world from the evil Crow Foods Corp.', 'none', 0, false),
    (261041, 'The Search for General Tso', 2014, '/wSPlCpa4LMN3xYNBdW6XcFUcSGu.jpg', '{99}', 'From New York City to the farmlands of the Midwest, there are 50,000 Chinese restaurants in the U.S., yet one dish in particular has conquered the American culinary landscape with a force befitting its military moniker—“General Tso’s Chicken.” But who was General Tso and how did this dish become so ubiquitous? Ian Cheney’s delightfully insightful documentary charts the history of Chinese Americans through the surprising origins of this sticky, sweet, just-spicy-enough dish that we’ve adopted as our own.', 'none', 0, false),
    (30298, 'The Secret of Santa Vittoria', 1969, '/uX4xHo8GptvEbkch6i7OpWiM1L0.jpg', '{18,35,10752}', 'During World War II, Italian villagers hide their wine from the German army.', 'nominee', 0, false),
    (8280, 'The Secret of the Grain', 2007, '/mqPwap2uS7d7yLJVGjQYTdG9I1P.jpg', '{18}', 'In southern France, a Franco-Arabic shipyard worker along with his partner''s daughter pursues his dream of opening a restaurant.', 'none', 14693300, false),
    (34423, 'The Slammin'' Salmon', 2009, '/yX9skMoAc1JAimJFtczEif4f1jS.jpg', '{35}', 'The brutal former heavyweight boxing champion Cleon "Slammin''" Salmon (Duncan), now owner of a Miami restaurant, institutes a competition to see which waiter can earn the most money in one night: the winner stands to gain $10,000, while the loser will endure a beating at the hands of the champ.', 'none', 60421, false),
    (58690, 'The Vineyard', 1989, '/hwxlCwHwUAoLCXkdV4053l6hYF1.jpg', '{27}', 'Dr. Elson Po is one of the world''s most famous wine growers and has a magic potion which has kept him handsome and alive for centuries. However, the magic which rejuvenates him seems to become less and less effective. As a side project, he makes movies and invites a group of young, aspiring actors to his island for a party, believing that the young, beautiful actress, Jezebel, can be his new source of life.', 'none', 0, false),
    (657766, 'The White Horse Inn', 1926, '/4yyxwdnDEe7zaQQk32ErWJZFbTZ.jpg', '{35}', 'Based on the play of the same name by Oskar Blumenthal and Gustav Kadelburg.', 'none', 0, false),
    (303912, 'The White Horse Inn', 1935, '/z4OEaxYYbqIbU1chpSCfwCCgtYB.jpg', '{}', 'Im weißen Rößl (English title: White Horse Inn or The White Horse Inn) is an operetta or musical comedy by Ralph Benatzky and Robert Stolz in collaboration with a number of other composers and writers, set in the picturesque Salzkammergut region of Upper Austria. It is about the head waiter of the White Horse Inn in St. Wolfgang who is desperately in love with the owner of the inn, a resolute young woman who at first only has eyes for one of her regular guests.', 'none', 0, false),
    (177290, 'The White Horse Inn', 1952, '/jZAz4ikGN6pQ6yJdmT4lhyEPk7Q.jpg', '{35,10402,10749}', 'Head waiter Leopold has been secretly in love with the hostess Josepha for a long time, but she only has eyes for Dr. Siedler, a guest in the White Horse Inn.  Leopold tries to get Dr. Siedler interested in the daughter of Industrialist Giesecke, who would rather see his daughter married to Sigismund.', 'none', 0, false),
    (6792, 'The White Horse Inn', 1960, '/osykq2Sgw3odStIESCm6DgkrSeE.jpg', '{35}', 'Leopold, head waiter at the "Weißen Rössl" (White Horse Inn), is secretly in love with the owner of the restaurant, Josepha. But she''s only interested in the lawyer Dr. Siedler. Jealous, Leopold comes up with a plan to gain Josepha''s attention.', 'none', 0, false),
    (761, 'The Wing or the Thigh?', 1976, '/ywkIu5l3iAgPZvLFEVBDYxLouH8.jpg', '{35}', 'Charles Duchemin, a well-known gourmet and publisher of a famous restaurant guide, is waging a war against fast food entrepreneur Tri- catel to save the French art of cooking. After having agreed to appear on a talk show to show his skills in naming food and wine by taste, he is confronted with two disasters: his son wants to become a clown rather than a restaurant tester and he, the famous Charles Duchemin, has lost his taste!', 'none', 0, false),
    (107985, 'The World''s End', 2013, '/kpglnOBYmKn0AkkWDzGxzKHDbds.jpg', '{28,35}', 'Five friends who reunite in an attempt to top their epic pub crawl from 20 years earlier unwittingly become humankind''s only hope for survival.', 'none', 46100000, false),
    (131898, 'This Earth Is Mine', 1959, '/bTPfkKlz3Mmqv2sOj2V6gkw8Cd9.jpg', '{18}', 'Set during the Prohibition era, when wine makers were financially challenged and had to decide whether or not they wanted to cooperate with bootleggers to survive.', 'none', 0, false),
    (46641, 'Today''s Special', 2009, '/lil1zu2THmFE0p6vHiqvod1kgIn.jpg', '{35,10749}', 'Young Manhattan chef Samir rediscovers his heritage and passion for life through the enchanting art of cooking Indian food.', 'none', 400654, false),
    (455411, 'Tom and Jerry: Willy Wonka & the Chocolate Factory', 2017, '/pzWt8ECED9kGm4LSXLSkPGBWpjE.jpg', '{12,14,16,35,10751}', 'The classic Roald Dahl tale gets a modern twist when Tom and Jerry enter the amazing world of Willy Wonka''s Chocolate Factory.', 'none', 0, false),
    (15104, 'Tortilla Soup', 2001, '/2JTgaodnScJHIyRrQTtaawOd949.jpg', '{18,35,10749}', 'A Mexican-American master chef and father to three daughters has lost his taste for food but not for life.', 'none', 4634077, false),
    (234759, 'Trip for Tat', 1960, '/pPMsweM7FQP5O5ZxlgWdBUQze3X.jpg', '{16,35,10751}', 'Tweety Bird goes on a world tour with his mistress, Granny. And a hungry Sylvester Cat follows them everywhere they go (France, Japan, Switzerland, and Italy).', 'none', 0, false),
    (229114, 'The Taste of Fish', 2008, '/3v1q1n7EF3IxLbHULuIiZJ0oQBd.jpg', '{18,35}', 'It may sound cliché, but Japanese people really do love their fish. If Japan has the best and freshest fish in the world, then Tokyo''s Tsukiji Fish Market is where you''re most likely to find them. It''s the home of Japan''s biggest daily fish auction, and it''s a place of fierce competition between fish merchants that have been in the business for generations.  Based on a comic series, The Taste of Fish follows businessman Shuntaro, who has a successful career in a trading company and is in a steady relationship with girlfriend Asuka. One day, Shuntaro has to help out at the fish wholesaler store run by Asuka''s father, and he immediately falls in love with the world of Tsukiji Fish Market. Soon, Shuntaro quits his job and devotes all of his time to running the business while learning about the market''s fascinating set of long-standing traditions. However, he must first also learn to distinguish the tastes of different fishes before he can survive in the competitive world of Tsukiji.', 'none', 0, false),
    (16622, 'A Good Beer', NULL, '/osv0TcCymlsOucqkZBssSuS4tD.jpg', '{16}', 'One of the first animated short films. A wanderer enters a cabaret in the countryside and asks a waitress for a beer. She comes back with a pint, as the wanderer begins to court her. However, the kitchen boy comes, drinks the beer and vanishes. The wanderer, misunderstanding, asks for another beer. Then a traveler enters and has an argument with the wandered. During the argument, the kitchen boy appears, sips the second beer and runs away. As the traveler quits, the customer finds his glass empty again. He calls the waitress, expresses his disappointment and leaves. The kitchen boy comes in and explains to the waitress what he did with the two beers. They make fun together of the wanderer and leave. A lost film.', 'none', 0, false),
    (264419, 'Huevos: Little Rooster''s Egg-Cellent Adventure', 2015, '/6ZkiGjyBcP1KAbpBYHwdVclpYqa.jpg', '{12,16,35,10751}', 'Toto has grown and now is a young cock. An evil rancher tricks the female owner of the ranch where they live and forces her to bet the property in a cockfight in the arena. Toto is the only option to defend their home, so he must train in just one week and win the championship of the arena.', 'none', 26072723, true),
    (573164, 'An Egg Rescue', 2021, '/Lgdvab8MvgdXyXnafbwoYTNvRT.jpg', '{12,16,35,10751}', 'Toto and his friends must rescue his egg children after they''re taken away for a gourmet food event in Africa.', 'none', 4093345, true),
    (16761, 'A Movie of Eggs', 2005, '/eHqGqr5xBat3P2b9YdRbKMLli4J.jpg', '{16,35,10751}', 'A small egg named Toto decides that he wants to fulfill his purpose in life and become a chicken instead of dying in a frying pan; so he starts a quest to return to the farms along with his new friend, the noisy egg Willy and a crazy bacon stripe. The three friends will face lot of obstacles in their quest.', 'none', 7144638, false),
    (200528, 'Unacceptable Levels', 2013, NULL, '{99}', 'Our bodies are changing, as synthetic chemicals are becoming an everyday experience for all of us. Every single human being on this planet is experiencing this, as we are constantly exposed on a daily basis to substances that our bodies have never seen before. At the same time, nearly all of our disease rates are rising, and many in the medical community are only now discovering, how much our lifestyles are affecting our own bodies, and those of the most vulnerable population, our children. Filmed all over the globe, ''Unacceptable Levels'' pulls back the curtain on how these chemicals are getting into our bodies, and it also reveals that there is hope inside of all of our challenges.', 'none', 0, false),
    (660609, 'Uncorked', 2020, '/neUgCuBhafxYQyXTKxwjQejqqa7.jpg', '{18,35}', 'Elijah must balance his dream of becoming a master sommelier with his father''s expectations that he carry on the family''s Memphis BBQ joint.', 'none', 0, false),
    (44018, 'Vagabond', 1985, '/2KFfwiPct1hwqi9dkKqoom0BenC.jpg', '{18}', 'Mona Bergeron is dead, her frozen body found in a ditch in the French countryside. From this, the film flashes back to the weeks leading up to her death. Through these flashbacks, Mona gradually declines as she travels from place to place, taking odd jobs and staying with whomever will offer her a place to sleep. Mona is fiercely independent, craving freedom over comfort, but it is this desire to be free that will eventually lead to her demise.', 'none', 8100000, false),
    (7093, 'Vatel', 2000, '/qxtzOlO5FqFgSOGnNr0kFzo2Ho7.jpg', '{18,36,10749}', 'Vatel is the cook of Prince Condé. When the prince invites Louis XIV to hunt, he has to give lavish banquets in order to fall in his favour. But when Vatel falls in love with the king''s mistress, love and duty conflict.', 'nominee', 184301, false),
    (76127, 'Vegucated', 2011, '/jKXD994yp5b95lXK7aGhGSGPysF.jpg', '{99}', 'Explores the challenges of converting to a vegan diet. It "follows three meat-and-cheese-loving New Yorkers who agree to adopt a vegan diet for six weeks.', 'none', 0, false),
    (268902, 'Vienna Tales', 1940, '/ApGV2IGpQVTkyAnromrawwyoWTB.jpg', '{35,10402}', 'A nostalgic story about life in and around a classic Vienna coffee house.  The film is set in Imperial Vienna at the beginning of the twentieth century.', 'none', 0, false),
    (75996, 'Waiter!', 1983, '/bssRyOxsXcJYcn7clqjcvFiEYqY.jpg', '{18,35,10749}', 'After a tumultuous life, a middle-aged headwaiter in a Parisian restaurant dreams of opening a seaside amusement park. When an old flame reappears, he reignites his feelings, but she is involved with another man.', 'none', 0, false),
    (7553, 'Waiting...', 2005, '/h3NJDiaaliUH35ApXPu8PFKZwWz.jpg', '{35}', 'Young employees at Shenaniganz restaurant collectively stave off boredom and adulthood with their antics.', 'none', 18637690, false),
    (10758, 'Waitress', 2007, '/ux3SPTHHmJytSjWEaV7xlo9nbOZ.jpg', '{18,35,10749}', 'A small town waitress stuck in a lousy marriage finds love when an exciting out-of-towner enters her life.', 'none', 22240529, false),
    (31073, 'West Bank Story', 2005, '/8rPnmd0GJrcyXp6rFsWIOXvPuGc.jpg', '{35,10402}', 'A musical comedy set in the fast-paced, fast-food world of competing falafel stands in the West Bank... David, an Israeli soldier, falls in love with the beautiful Palestinian cashier, Fatima, despite the animosity between their families'' dueling restaurants. Can the couple''s love withstand a 2000-year-old conflict and their families'' desire to control the future of the chickpea in the Middle East?', 'none', 0, false),
    (53576, 'What! No Beer?', 1933, '/4mshE4EOh2LhwZLM7nEqxzKscTf.jpg', '{35}', 'When Prohibition ends, a barber tries to get in the liquor business only to come up against mobsters.', 'none', 0, false),
    (90967, 'When You Comin'' Back, Red Ryder?', 1979, '/btsWEWBfIpHB5Bbebol0wUn0Hk.jpg', '{18}', 'A drug dealer''s car breaks down in a small U.S. town. In turn, the town''s people become victim to his unique brand of physical and mental torture.', 'none', 0, false),
    (16665, 'Whisky Galore!', 1949, '/4qz5Oc3hgXx4eBx7vkqLfG58J9X.jpg', '{35,80}', 'Scottish islanders try to plunder 50,000 cases of whisky from a stranded ship.', 'none', 0, false),
    (4984, 'White Lightning', 1973, '/z8eAIC67eaM2h1dFZvnifq7P8ln.jpg', '{18,28,80}', 'An ex-con teams up with federal agents to help them with breaking up a moonshine ring.', 'none', 0, false),
    (42216, 'Who Is Killing the Great Chefs of Europe?', 1978, '/N98Pdb4hdNqZsYO5bBXXb897RS.jpg', '{35,80,9648}', 'Mystery abounds when it is discovered that, one by one, the greatest chefs in Europe are being killed. The intriguing part of the murders is that each chef is killed in the same manner that their own special dish is prepared in. Food critics and the (many) self-proclaimed greatest chefs in Europe demand the mystery be solved.', 'none', 0, false),
    (252, 'Willy Wonka & the Chocolate Factory', 1971, '/vmpsZkrs4Uvkp9r1atL8B3frA63.jpg', '{14,35,10751}', 'When eccentric candy man Willy Wonka promises a lifetime supply of sweets and a tour of his chocolate factory to five lucky kids, penniless Charlie Bucket seeks the golden ticket that will make him a winner.', 'nominee', 2361799, false),
    (513083, 'Wine Country', 2019, '/mi5l29DQFdwrTXxbqM2OLbs830H.jpg', '{35}', 'A group of friends head to the land of oaky Chardonnays and big, bold Cabernet Sauvignons for one member of the squad’s 50th birthday party.', 'none', 0, false),
    (29281, 'Wine for the Confused', 2004, '/cm3oAL3CMmnyco0ICoA4XqbXLFg.jpg', '{99}', 'Wine is confusing…overwhelming even. So where do you start if you want to learn more about it? Join John Cleese on an entertaining and personal look at the world of winemaking and discover: how to find wines that taste good to you, how to make sure you get the best value and how to keep and serve wine at home.', 'none', 0, false),
    (14629, 'Woman on Top', 2000, '/eYHvcMeVjWPwATYI0VCdecMy2n3.jpg', '{14,18,35,10749}', 'Set to the intoxicating rhythms of Brazil, "Woman on Top" is a spicy, sexy comedy about the magic of food, love and music. Meet Isabella, a sultry enchantress born with the special gift of melting the palates and hearts of men everywhere. When she decides to break free from her rocky marriage and the stifling kitchen of her husband''s restaurant in Brazil, she spirits off to San Francisco in pursuit of her dreams of a real culinary career.', 'none', 10194274, false),
    (787699, 'Wonka', 2023, '/qhb1qOilapbapxWQn9jtRCMwXJF.jpg', '{14,35,10751}', 'Willy Wonka – chock-full of ideas and determined to change the world one delectable bite at a time – is proof that the best things in life begin with a dream, and if you’re lucky enough to meet Willy Wonka, anything is possible.', 'none', 634502312, false),
    (44941, 'Year of the Comet', 1992, '/qZSn3HyI5B2jQnoPQPYxCkAgbMm.jpg', '{12}', 'An auctioneer''s daughter and a rich buyer''s emissary fall for each other while trying to keep a rare wine out of the hands of evil doers.', 'none', 0, false)
) AS v(tmdb_id, title, year, poster, genres, overview, oscar, revenue, is_sequel)
WHERE sd.slug = 'food-and-drink-movies'
ON CONFLICT (spec_draft_id, movie_tmdb_id) DO NOTHING;

