-- Check: should show 244 movies and 76 in Restaurants.
SELECT
  (SELECT count(*) FROM public.spec_draft_movies m JOIN public.spec_drafts sd ON sd.id = m.spec_draft_id WHERE sd.slug = 'food-and-drink-movies') AS movies,
  (SELECT count(*) FROM public.spec_draft_movie_categories c
     JOIN public.spec_draft_movies m ON m.id = c.spec_draft_movie_id
     JOIN public.spec_drafts sd ON sd.id = m.spec_draft_id
   WHERE sd.slug = 'food-and-drink-movies' AND c.category_name = 'Restaurants') AS in_restaurants;
